'use strict';
const K={shifts:'msr_shifts_v1',profile:'msr_profile_v1',active:'msr_active_v1',settings:'msr_settings_v1',employers:'msr_employers_v2',payrolls:'msr_payrolls_v3',scheduled:'msr_scheduled_v3',debts:'msr_debts_v3'};
const read=(k,d)=>{try{const v=localStorage.getItem(k);return v?JSON.parse(v):d}catch(e){return d}};
const put=(k,v)=>localStorage.setItem(k,JSON.stringify(v));
let shifts=read(K.shifts,[]),profile=read(K.profile,{}),active=read(K.active,null),settings=read(K.settings,{role:'Security Officer'}),employers=read(K.employers,[]),payrolls=read(K.payrolls,[]),scheduled=read(K.scheduled,[]),debts=read(K.debts,[]),timerHandle=null,pendingRestore=null,payrollModalMode='receive',moneyTab='salary';
const pad=n=>String(n).padStart(2,'0');
const uid=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,8);
const localDate=(d=new Date())=>d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate());
const localTime=(d=new Date())=>pad(d.getHours())+':'+pad(d.getMinutes());
const currentMonth=()=>localDate().slice(0,7);
const niceDate=s=>{if(!s)return'';const [y,m,d]=s.split('-');return d+'/'+m+'/'+y};
const dayName=s=>new Date(s+'T12:00:00').toLocaleDateString('en-GB',{weekday:'short'});
const monthName=s=>{if(s==='all')return'General / unallocated';if(!s)return'';const [y,m]=s.split('-');return new Date(Number(y),Number(m)-1,1).toLocaleDateString('en-GB',{month:'long',year:'numeric'})};
const money=n=>'£'+(Number(n)||0).toFixed(2);
const hm=m=>Math.floor((Number(m)||0)/60)+'h '+pad((Number(m)||0)%60)+'m';
const decimal=m=>((Number(m)||0)/60).toFixed(2);
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const native=()=>typeof AndroidBridge!=='undefined';
const clone=v=>JSON.parse(JSON.stringify(v));
function toast(msg){const t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');clearTimeout(t._h);t._h=setTimeout(()=>t.classList.remove('show'),2800)}
function employerById(id){return employers.find(e=>e.id===id)||null}
function siteById(emp,id){return emp?.sites?.find(s=>s.id===id)||null}
function employerName(s){return s.employerName||employerById(s.employerId)?.name||'Unassigned'}
function daysInMonth(year,month){return new Date(year,month,0).getDate()}
function monthBounds(month){const [y,m]=month.split('-').map(Number);return{from:month+'-01',to:month+'-'+pad(daysInMonth(y,m))}}
function addMonths(month,offset){const [y,m]=month.split('-').map(Number),d=new Date(y,m-1+Number(offset||0),1);return d.getFullYear()+'-'+pad(d.getMonth()+1)}
function expectedPayDate(emp,earnedMonth){const target=addMonths(earnedMonth,Number(emp?.payOffset??1)),[y,m]=target.split('-').map(Number),day=Math.min(Math.max(1,Number(emp?.payDay)||1),daysInMonth(y,m));return target+'-'+pad(day)}
function dateTimeMs(date,time='09:00'){const d=new Date(date+'T'+time+':00');return d.getTime()}
function reminderStatus(date){if(!date)return'';const today=localDate();if(date<today)return'overdue';if(date===today)return'due';return'future'}
function migrate(){
  if(!Array.isArray(shifts))shifts=[];if(!Array.isArray(employers))employers=[];if(!Array.isArray(payrolls))payrolls=[];if(!Array.isArray(scheduled))scheduled=[];if(!Array.isArray(debts))debts=[];
  const hasLegacy=shifts.length||profile.employer||settings.location||settings.rate;
  if(!employers.length&&hasLegacy){const e={id:uid(),name:(profile.employer||'Existing Employer').trim(),defaultRate:Number(settings.rate)||0,payrollRef:'',payDay:1,payOffset:1,notes:'Imported from an earlier app version',sites:[]};if(settings.location)e.sites.push({id:uid(),name:String(settings.location).trim(),address:'',rateOverride:null,latitude:null,longitude:null,accuracy:null,capturedAt:''});employers.push(e);settings.defaultEmployerId=e.id}
  employers.forEach(e=>{if(!Array.isArray(e.sites))e.sites=[];e.defaultRate=Number(e.defaultRate)||0;e.payDay=Math.min(31,Math.max(1,Number(e.payDay)||1));e.payOffset=[0,1,2].includes(Number(e.payOffset))?Number(e.payOffset):1;e.sites=e.sites.map(s=>({...s,rateOverride:s.rateOverride===undefined?null:s.rateOverride,latitude:s.latitude===null||s.latitude===''||!Number.isFinite(Number(s.latitude))?null:Number(s.latitude),longitude:s.longitude===null||s.longitude===''||!Number.isFinite(Number(s.longitude))?null:Number(s.longitude),accuracy:s.accuracy===null||s.accuracy===''||!Number.isFinite(Number(s.accuracy))?null:Number(s.accuracy),capturedAt:s.capturedAt||''}))});
  const fallback=employers[0];
  shifts=shifts.map(s=>{let x={...s,earnedMonth:s.earnedMonth||String(s.date||'').slice(0,7),additional:Number(s.additional)||0,deduction:Number(s.deduction)||0,total:Number(s.total)||0};if(!x.employerId&&fallback){const matched=fallback.sites.find(z=>z.name.toLowerCase()===String(x.location||'').toLowerCase());x={...x,employerId:fallback.id,employerName:fallback.name,siteId:matched?.id||'',siteLatitude:matched?.latitude??null,siteLongitude:matched?.longitude??null,siteAccuracy:matched?.accuracy??null}}return{...x,employerName:employerName(x)}});
  if(active&&!active.employerId&&fallback)active={...active,employerId:fallback.id,employerName:fallback.name};
  payrolls=payrolls.map(p=>({...p,id:p.id||uid(),receipts:Array.isArray(p.receipts)?p.receipts:[],promises:Array.isArray(p.promises)?p.promises:[],notes:p.notes||''}));
  scheduled=scheduled.map(s=>({...s,id:s.id||uid(),status:s.status||'planned',reminderMinutes:Number(s.reminderMinutes??60),rate:Number(s.rate)||0}));
  debts=debts.map(d=>({...d,id:d.id||uid(),direction:d.direction==='i_owe'?'i_owe':'owed_to_me',amount:Number(d.amount)||0,payments:Array.isArray(d.payments)?d.payments:[],dueDate:d.dueDate||'',status:d.status||'open'}));
  if(settings.defaultEmployerId&&!employerById(settings.defaultEmployerId))settings.defaultEmployerId=fallback?.id||'';
  persist(false);
}
function persist(doRender=true){put(K.shifts,shifts);put(K.profile,profile);put(K.active,active);put(K.settings,settings);put(K.employers,employers);put(K.payrolls,payrolls);put(K.scheduled,scheduled);put(K.debts,debts);if(doRender)renderAll()}
migrate();
function dataBundle(){return{app:'Job Buddy',version:'4.5',exportedAt:new Date().toISOString(),profile,settings,employers,active,shifts,payrolls,scheduled,debts}}
function saveAll(doBackup=true){persist(true);syncAllReminders(false);if(doBackup)backupNow(false)}
function go(p){document.querySelectorAll('.page').forEach(x=>x.classList.remove('active'));document.getElementById(p+'Page').classList.add('active');document.querySelectorAll('.nav button').forEach(x=>x.classList.toggle('active',x.dataset.page===p));document.getElementById('topSubtitle').textContent={dashboard:'Track hours, wages and payments',history:'Completed and scheduled shifts',employers:'Employers, rates, pay dates and sites',timesheet:'Monthly and custom timesheet exports',money:'Salary balances, instalments and personal diary',profile:'Personal and bank information',settings:'Reminders, backup and data'}[p];if(p==='history')renderHistory();if(p==='employers')renderEmployers();if(p==='timesheet')renderTimesheet();if(p==='money')renderMoney();if(p==='settings')loadSettings();window.scrollTo(0,0)}
function calculate(date,start,end,breakMin,rate,additional=0,deduction=0){const st=new Date(date+'T'+start+':00'),en=new Date(date+'T'+end+':00');if(en<=st)en.setDate(en.getDate()+1);const gross=Math.max(0,Math.round((en-st)/60000)),paid=Math.max(0,gross-breakMin),total=paid/60*rate+additional-deduction;return{gross,paid,total:Number(total.toFixed(2)),endDate:localDate(en)}}
function rateFor(empId,siteId){const e=employerById(empId),s=siteById(e,siteId);return s&&s.rateOverride!==null&&s.rateOverride!==''?Number(s.rateOverride):Number(e?.defaultRate||0)}
function fillEmployerSelect(elId,{includeAll=false,selected=''}={}){const el=document.getElementById(elId);if(!el)return;let html=includeAll?'<option value="all">All employers combined</option>':'<option value="">Select employer</option>';html+=employers.map(e=>`<option value="${e.id}">${esc(e.name)} — ${money(e.defaultRate)}/hr</option>`).join('');el.innerHTML=html;if(selected&&[...el.options].some(o=>o.value===selected))el.value=selected;else if(!includeAll&&settings.defaultEmployerId&&[...el.options].some(o=>o.value===settings.defaultEmployerId))el.value=settings.defaultEmployerId}
function fillSiteSelect(elId,empId,selected='',customLocation=''){const el=document.getElementById(elId);if(!el)return;const e=employerById(empId);let html='<option value="">Select site</option>';html+=(e?.sites||[]).map(s=>`<option value="${s.id}">${esc(s.name)}${s.rateOverride!==null&&s.rateOverride!==''?' — '+money(s.rateOverride)+'/hr':''}</option>`).join('');html+='<option value="__custom">Other / custom location</option>';el.innerHTML=html;if(selected&&[...el.options].some(o=>o.value===selected))el.value=selected;else if(customLocation)el.value='__custom'}
function refreshSelectors(){const values={hist:document.getElementById('histEmployer')?.value||'all',ts:document.getElementById('tsEmployer')?.value||'all',set:document.getElementById('sEmployer')?.value||settings.defaultEmployerId||'',pay:document.getElementById('payrollEmployer')?.value||'all'};fillEmployerSelect('histEmployer',{includeAll:true,selected:values.hist});fillEmployerSelect('tsEmployer',{includeAll:true,selected:values.ts});fillEmployerSelect('sEmployer',{selected:values.set});fillEmployerSelect('payrollEmployer',{includeAll:true,selected:values.pay})}
function siteSelection(prefix){const empId=document.getElementById(prefix+'Employer').value,siteValue=document.getElementById(prefix+'Site').value,e=employerById(empId);if(!e)return null;if(siteValue==='__custom'){const location=document.getElementById(prefix+'CustomLocation').value.trim();return location?{employer:e,site:null,location,address:'',latitude:null,longitude:null,accuracy:null,capturedAt:''}:null}const s=siteById(e,siteValue);return s?{employer:e,site:s,location:s.name,address:s.address||'',latitude:s.latitude??null,longitude:s.longitude??null,accuracy:s.accuracy??null,capturedAt:s.capturedAt||''}:null}

function clockMain(){if(active){openClockOut();return}if(!employers.length){toast('Add an employer before clocking in');go('employers');return}openClockIn()}
function openClockIn(prefill=null){fillEmployerSelect('ciEmployer',{selected:prefill?.employerId||settings.defaultEmployerId||employers[0]?.id});if(prefill?.employerId)document.getElementById('ciEmployer').value=prefill.employerId;document.getElementById('ciRole').value=prefill?.role||settings.role||profile.job||'Security Officer';document.getElementById('ciCustomLocation').value=prefill&&!prefill.siteId?prefill.location||'':'';onClockEmployerChange(prefill?.siteId||'',prefill&&!prefill.siteId?prefill.location:'');if(prefill?.rate!==undefined)document.getElementById('ciRate').value=Number(prefill.rate).toFixed(2);document.getElementById('clockInModal').classList.add('open')}
function closeClockIn(){document.getElementById('clockInModal').classList.remove('open')}
function onClockEmployerChange(selected='',custom=''){const empId=document.getElementById('ciEmployer').value;fillSiteSelect('ciSite',empId,selected,custom);onClockSiteChange()}
function onClockSiteChange(){const empId=document.getElementById('ciEmployer').value,siteId=document.getElementById('ciSite').value;document.getElementById('ciCustomWrap').classList.toggle('hidden',siteId!=='__custom');document.getElementById('ciRate').value=rateFor(empId,siteId).toFixed(2)}
function startClock(){const selected=siteSelection('ci'),rate=Number(document.getElementById('ciRate').value);if(!selected||!(rate>=0)){toast('Select employer, location and a valid rate');return}active={id:uid(),startedAt:new Date().toISOString(),employerId:selected.employer.id,employerName:selected.employer.name,siteId:selected.site?.id||'',location:selected.location,siteAddress:selected.address,siteLatitude:selected.latitude,siteLongitude:selected.longitude,siteAccuracy:selected.accuracy,siteCapturedAt:selected.capturedAt,role:document.getElementById('ciRole').value.trim(),rate,scheduledId:window._startingScheduleId||''};if(window._startingScheduleId){const s=scheduled.find(x=>x.id===window._startingScheduleId);if(s)s.status='started';cancelNativeReminder('shift_'+window._startingScheduleId);window._startingScheduleId=''}closeClockIn();saveAll();toast('Clocked in at '+selected.location)}
function openClockOut(){const st=new Date(active.startedAt);document.getElementById('coSummary').innerHTML='<strong>'+esc(active.employerName)+'</strong><br>'+esc(active.location)+'<br>Started '+localTime(st)+' • '+money(active.rate)+'/hr';document.getElementById('coBreak').value=0;document.getElementById('coNotes').value='';document.getElementById('clockOutModal').classList.add('open')}
function closeClockOut(){document.getElementById('clockOutModal').classList.remove('open')}
function finishClock(){const st=new Date(active.startedAt),en=new Date(),breakMin=Math.max(0,Number(document.getElementById('coBreak').value)||0),gross=Math.max(0,Math.round((en-st)/60000)),paid=Math.max(0,gross-breakMin),total=paid/60*Number(active.rate||0),sid=active.scheduledId;shifts.push({id:active.id,date:localDate(st),earnedMonth:localDate(st).slice(0,7),start:localTime(st),end:localTime(en),endDate:localDate(en),employerId:active.employerId,employerName:active.employerName,siteId:active.siteId||'',location:active.location,siteAddress:active.siteAddress||'',siteLatitude:active.siteLatitude??null,siteLongitude:active.siteLongitude??null,siteAccuracy:active.siteAccuracy??null,role:active.role,breakMin,paidMinutes:paid,grossMinutes:gross,rate:Number(active.rate)||0,additional:0,deduction:0,total:Number(total.toFixed(2)),notes:document.getElementById('coNotes').value.trim(),method:'clock'});if(sid){const s=scheduled.find(x=>x.id===sid);if(s)s.status='completed'}active=null;closeClockOut();saveAll();toast('Shift completed and salary balance updated')}
function renderClock(){const btn=document.getElementById('clockMainBtn'),badge=document.getElementById('clockBadge');if(active){document.getElementById('clockState').textContent='Clocked in — '+active.employerName;document.getElementById('clockSite').textContent=active.location+' • '+(active.role||'Shift');badge.textContent='LIVE';badge.classList.add('live');btn.textContent='CLOCK OUT';btn.className='btn gold clockbtn';tick()}else{document.getElementById('clockState').textContent='Not clocked in';document.getElementById('clockSite').textContent=employers.length?'Ready for your next shift':'Add your first employer to begin';badge.textContent='OFF SHIFT';badge.classList.remove('live');btn.textContent='CLOCK IN';btn.className='btn primary clockbtn';document.getElementById('liveTimer').textContent='00:00:00'}}
function tick(){if(!active)return;const sec=Math.max(0,Math.floor((Date.now()-new Date(active.startedAt).getTime())/1000));document.getElementById('liveTimer').textContent=pad(Math.floor(sec/3600))+':'+pad(Math.floor(sec%3600/60))+':'+pad(sec%60)}

function openManual(id){if(!employers.length){toast('Add an employer before adding shifts');go('employers');return}const x=id?shifts.find(s=>s.id===id):null;document.getElementById('modalTitle').textContent=x?'Edit completed shift':'Add completed shift';document.getElementById('mId').value=x?.id||'';const empId=x?.employerId||settings.defaultEmployerId||employers[0]?.id||'';fillEmployerSelect('mEmployer',{selected:empId});document.getElementById('mEmployer').value=empId;fillSiteSelect('mSite',empId,x?.siteId||'',x&&!x.siteId?x.location:'');document.getElementById('mCustomLocation').value=x&&!x.siteId?x.location||'':'';document.getElementById('mCustomWrap').classList.toggle('hidden',document.getElementById('mSite').value!=='__custom');document.getElementById('mDate').value=x?.date||localDate();document.getElementById('mRole').value=x?.role||settings.role||profile.job||'Security Officer';document.getElementById('mStart').value=x?.start||'08:00';document.getElementById('mEnd').value=x?.end||'20:00';document.getElementById('mBreak').value=x?.breakMin||0;document.getElementById('mRate').value=x?.rate??rateFor(empId,document.getElementById('mSite').value);document.getElementById('mAdditional').value=x?.additional||0;document.getElementById('mDeduction').value=x?.deduction||0;document.getElementById('mNotes').value=x?.notes||'';document.getElementById('shiftModal').classList.add('open')}
function closeModal(){document.getElementById('shiftModal').classList.remove('open')}
function onManualEmployerChange(){const empId=document.getElementById('mEmployer').value;fillSiteSelect('mSite',empId);onManualSiteChange()}
function onManualSiteChange(){const empId=document.getElementById('mEmployer').value,siteId=document.getElementById('mSite').value;document.getElementById('mCustomWrap').classList.toggle('hidden',siteId!=='__custom');document.getElementById('mRate').value=rateFor(empId,siteId).toFixed(2)}
function saveManual(){const selected=siteSelection('m'),date=document.getElementById('mDate').value,start=document.getElementById('mStart').value,end=document.getElementById('mEnd').value,rate=Number(document.getElementById('mRate').value);if(!selected||!date||!start||!end||!(rate>=0)){toast('Complete employer, location, date, times and rate');return}const breakMin=Math.max(0,Number(document.getElementById('mBreak').value)||0),additional=Number(document.getElementById('mAdditional').value)||0,deduction=Number(document.getElementById('mDeduction').value)||0,c=calculate(date,start,end,breakMin,rate,additional,deduction);if(c.gross>1080&&!confirm('This shift is longer than 18 hours. Save it anyway?'))return;const id=document.getElementById('mId').value||uid(),obj={id,date,earnedMonth:date.slice(0,7),start,end,endDate:c.endDate,employerId:selected.employer.id,employerName:selected.employer.name,siteId:selected.site?.id||'',location:selected.location,siteAddress:selected.address,siteLatitude:selected.latitude,siteLongitude:selected.longitude,siteAccuracy:selected.accuracy,role:document.getElementById('mRole').value.trim(),breakMin,paidMinutes:c.paid,grossMinutes:c.gross,rate,additional,deduction,total:c.total,notes:document.getElementById('mNotes').value.trim(),method:'manual'},i=shifts.findIndex(s=>s.id===id);if(i>=0)shifts[i]=obj;else shifts.push(obj);if(window._completingScheduleId){const sc=scheduled.find(z=>z.id===window._completingScheduleId);if(sc)sc.status='completed';cancelNativeReminder('shift_'+window._completingScheduleId);window._completingScheduleId=''}closeModal();saveAll();toast(i>=0?'Shift updated':'Shift added and salary balance updated')}
function duplicateShift(id){const x=shifts.find(s=>s.id===id);if(!x)return;const d=localDate();shifts.push({...x,id:uid(),date:d,earnedMonth:d.slice(0,7),method:'manual'});saveAll();toast('Shift duplicated for today')}
function deleteShift(id){if(!confirm('Delete this shift permanently? Salary totals will be recalculated.'))return;shifts=shifts.filter(s=>s.id!==id);saveAll();toast('Shift deleted')}
function shiftCard(s){return`<div class="shift"><div class="shifthead"><div><h3>${esc(s.location)}</h3><div class="meta"><strong>${esc(employerName(s))}</strong><br>${niceDate(s.date)} (${dayName(s.date)}) • ${esc(s.role||'Shift')}<br>${s.start}–${s.end}${s.endDate&&s.endDate!==s.date?' next day':''} • Break ${s.breakMin||0}m • ${hm(s.paidMinutes)} • ${money(s.rate)}/hr</div></div><div class="money">${money(s.total)}</div></div><div class="actions"><button class="mini" onclick="openManual('${s.id}')">Edit</button><button class="mini" onclick="duplicateShift('${s.id}')">Duplicate</button><button class="mini" onclick="deleteShift('${s.id}')">Delete</button></div></div>`}

function openSchedule(id){if(!employers.length){toast('Add an employer before scheduling shifts');go('employers');return}const x=id?scheduled.find(s=>s.id===id):null;document.getElementById('scheduleTitle').textContent=x?'Edit scheduled shift':'Schedule future shift';document.getElementById('schId').value=x?.id||'';const empId=x?.employerId||settings.defaultEmployerId||employers[0]?.id||'';fillEmployerSelect('schEmployer',{selected:empId});document.getElementById('schEmployer').value=empId;fillSiteSelect('schSite',empId,x?.siteId||'',x&&!x.siteId?x.location:'');document.getElementById('schCustomLocation').value=x&&!x.siteId?x.location||'':'';document.getElementById('schCustomWrap').classList.toggle('hidden',document.getElementById('schSite').value!=='__custom');const tomorrow=new Date();tomorrow.setDate(tomorrow.getDate()+1);document.getElementById('schDate').value=x?.date||localDate(tomorrow);document.getElementById('schRole').value=x?.role||settings.role||profile.job||'Security Officer';document.getElementById('schStart').value=x?.start||'08:00';document.getElementById('schEnd').value=x?.end||'20:00';document.getElementById('schRate').value=x?.rate??rateFor(empId,document.getElementById('schSite').value);document.getElementById('schReminder').value=String(x?.reminderMinutes??60);document.getElementById('schNotes').value=x?.notes||'';document.getElementById('scheduleModal').classList.add('open')}
function closeSchedule(){document.getElementById('scheduleModal').classList.remove('open')}
function onScheduleEmployerChange(){const empId=document.getElementById('schEmployer').value;fillSiteSelect('schSite',empId);onScheduleSiteChange()}
function onScheduleSiteChange(){const empId=document.getElementById('schEmployer').value,siteId=document.getElementById('schSite').value;document.getElementById('schCustomWrap').classList.toggle('hidden',siteId!=='__custom');document.getElementById('schRate').value=rateFor(empId,siteId).toFixed(2)}
function scheduledReminderMs(s){return dateTimeMs(s.date,s.start)-Number(s.reminderMinutes||0)*60000}
function saveScheduledShift(){const selected=siteSelection('sch'),date=document.getElementById('schDate').value,start=document.getElementById('schStart').value,end=document.getElementById('schEnd').value,rate=Number(document.getElementById('schRate').value);if(!selected||!date||!start||!end||!(rate>=0)){toast('Complete employer, location, date, times and rate');return}const id=document.getElementById('schId').value||uid(),old=scheduled.find(s=>s.id===id),obj={id,date,start,end,employerId:selected.employer.id,employerName:selected.employer.name,siteId:selected.site?.id||'',location:selected.location,siteAddress:selected.address,siteLatitude:selected.latitude,siteLongitude:selected.longitude,role:document.getElementById('schRole').value.trim(),rate,reminderMinutes:Number(document.getElementById('schReminder').value)||0,notes:document.getElementById('schNotes').value.trim(),status:old?.status==='started'?'started':'planned'},i=scheduled.findIndex(s=>s.id===id);if(i>=0)scheduled[i]=obj;else scheduled.push(obj);closeSchedule();saveAll();toast(i>=0?'Scheduled shift updated':'Shift scheduled with reminder')}
function startScheduledShift(id){if(active){toast('You already have an active shift');return}const s=scheduled.find(x=>x.id===id);if(!s)return;window._startingScheduleId=id;openClockIn(s)}
function completeScheduledManually(id){const s=scheduled.find(x=>x.id===id);if(!s)return;openManual();setTimeout(()=>{document.getElementById('mEmployer').value=s.employerId;fillSiteSelect('mSite',s.employerId,s.siteId,s.siteId?'':s.location);document.getElementById('mCustomLocation').value=s.siteId?'':s.location;document.getElementById('mCustomWrap').classList.toggle('hidden',document.getElementById('mSite').value!=='__custom');document.getElementById('mDate').value=s.date;document.getElementById('mRole').value=s.role;document.getElementById('mStart').value=s.start;document.getElementById('mEnd').value=s.end;document.getElementById('mRate').value=s.rate;document.getElementById('mNotes').value=s.notes||'';window._completingScheduleId=id},50)}
function deleteScheduledShift(id){if(!confirm('Delete this scheduled shift and its reminder?'))return;scheduled=scheduled.filter(s=>s.id!==id);cancelNativeReminder('shift_'+id);saveAll();toast('Scheduled shift deleted')}
function scheduledCard(s){const status=s.status==='completed'?'<span class="pill paid">Completed</span>':s.status==='started'?'<span class="pill warn">Started</span>':s.date<localDate()?'<span class="pill danger">Past</span>':'<span class="pill">Planned</span>';return`<div class="reminder-entry"><div class="entryhead"><div><h3>${esc(s.location)}</h3><div class="meta"><strong>${esc(employerName(s))}</strong><br>${niceDate(s.date)} (${dayName(s.date)}) • ${s.start}–${s.end}<br>${esc(s.role||'Shift')} • ${money(s.rate)}/hr • reminder ${s.reminderMinutes?Math.round(s.reminderMinutes/60*10)/10+'h before':'at start'}</div></div>${status}</div><div class="actions">${s.status==='planned'?`<button class="mini" onclick="startScheduledShift('${s.id}')">Clock in</button><button class="mini" onclick="completeScheduledManually('${s.id}')">Add completed</button><button class="mini" onclick="openSchedule('${s.id}')">Edit</button>`:''}<button class="mini" onclick="deleteScheduledShift('${s.id}')">Delete</button></div></div>`}

function renderHistory(){let a=[...shifts].sort((x,y)=>(y.date+y.start).localeCompare(x.date+x.start)),f=document.getElementById('histFrom').value,t=document.getElementById('histTo').value,q=document.getElementById('histSearch').value.trim().toLowerCase(),emp=document.getElementById('histEmployer').value;if(f)a=a.filter(x=>x.date>=f);if(t)a=a.filter(x=>x.date<=t);if(emp&&emp!=='all')a=a.filter(x=>x.employerId===emp);if(q)a=a.filter(x=>(employerName(x)+' '+x.location+' '+x.role+' '+x.notes).toLowerCase().includes(q));document.getElementById('historyList').innerHTML=a.length?a.map(shiftCard).join(''):'<div class="empty">No completed shifts match these filters.</div>';let sc=[...scheduled].filter(x=>x.status!=='completed').sort((a,b)=>(a.date+a.start).localeCompare(b.date+b.start));if(emp&&emp!=='all')sc=sc.filter(x=>x.employerId===emp);if(q)sc=sc.filter(x=>(employerName(x)+' '+x.location+' '+x.role+' '+x.notes).toLowerCase().includes(q));document.getElementById('scheduledList').innerHTML=sc.length?sc.map(scheduledCard).join(''):'<div class="empty">No scheduled shifts.</div>';document.getElementById('historyScheduledCount').textContent=sc.length}
function sumRange(from,to){const a=shifts.filter(s=>s.date>=from&&s.date<=to);return{mins:a.reduce((n,s)=>n+Number(s.paidMinutes||0),0),pay:a.reduce((n,s)=>n+Number(s.total||0),0),count:a.length}}

function openEmployer(id){const e=id?employerById(id):null;document.getElementById('employerModalTitle').textContent=e?'Edit employer':'Add employer';document.getElementById('eId').value=e?.id||'';document.getElementById('eName').value=e?.name||'';document.getElementById('eRate').value=e?.defaultRate??'';document.getElementById('ePayroll').value=e?.payrollRef||'';document.getElementById('ePayDay').value=e?.payDay??1;document.getElementById('ePayOffset').value=String(e?.payOffset??1);document.getElementById('eNotes').value=e?.notes||'';document.getElementById('employerModal').classList.add('open')}
function closeEmployer(){document.getElementById('employerModal').classList.remove('open')}
function saveEmployer(){const id=document.getElementById('eId').value||uid(),name=document.getElementById('eName').value.trim(),rate=Number(document.getElementById('eRate').value),payDay=Math.min(31,Math.max(1,Number(document.getElementById('ePayDay').value)||1)),payOffset=Number(document.getElementById('ePayOffset').value)||0;if(!name||!(rate>=0)){toast('Enter employer name and valid rate');return}const i=employers.findIndex(e=>e.id===id),old=i>=0?employers[i]:null,obj={id,name,defaultRate:rate,payrollRef:document.getElementById('ePayroll').value.trim(),payDay,payOffset,notes:document.getElementById('eNotes').value.trim(),sites:old?.sites||[]};if(i>=0)employers[i]=obj;else employers.push(obj);shifts=shifts.map(s=>s.employerId===id?{...s,employerName:name}:s);scheduled=scheduled.map(s=>s.employerId===id?{...s,employerName:name}:s);if(active?.employerId===id)active.employerName=name;if(!settings.defaultEmployerId)settings.defaultEmployerId=id;closeEmployer();saveAll();toast(i>=0?'Employer updated':'Employer added')}
function deleteEmployer(id){if(shifts.some(s=>s.employerId===id)||scheduled.some(s=>s.employerId===id)||payrolls.some(p=>p.employerId===id)){toast('This employer has shifts, schedules or payment records and cannot be deleted');return}if(!confirm('Delete this employer and all its saved sites?'))return;employers=employers.filter(e=>e.id!==id);if(settings.defaultEmployerId===id)settings.defaultEmployerId=employers[0]?.id||'';saveAll();toast('Employer deleted')}
function openSite(empId,siteId){const e=employerById(empId),s=siteId?siteById(e,siteId):null;if(!e)return;document.getElementById('siteModalTitle').textContent=s?'Edit site':'Add site for '+e.name;document.getElementById('siteEmployerId').value=empId;document.getElementById('siteId').value=s?.id||'';document.getElementById('siteName').value=s?.name||'';document.getElementById('siteAddress').value=s?.address||'';document.getElementById('siteRate').value=s?.rateOverride??'';document.getElementById('siteLatitude').value=s?.latitude??'';document.getElementById('siteLongitude').value=s?.longitude??'';document.getElementById('siteAccuracy').value=s?.accuracy??'';document.getElementById('siteCapturedAt').value=s?.capturedAt||'';updateSiteGpsStatus();document.getElementById('siteModal').classList.add('open')}
function closeSite(){document.getElementById('siteModal').classList.remove('open')}
function saveSite(){const empId=document.getElementById('siteEmployerId').value,e=employerById(empId);if(!e)return;const id=document.getElementById('siteId').value,name=document.getElementById('siteName').value.trim(),address=document.getElementById('siteAddress').value.trim(),rateRaw=document.getElementById('siteRate').value,rateOverride=rateRaw===''?null:Number(rateRaw),latRaw=document.getElementById('siteLatitude').value,lonRaw=document.getElementById('siteLongitude').value;if(!name||(rateOverride!==null&&!(rateOverride>=0))){toast('Enter site name and a valid optional rate');return}if((latRaw===''&&lonRaw!=='')||(latRaw!==''&&lonRaw==='')){toast('Enter both latitude and longitude, or leave both blank');return}const latitude=latRaw===''?null:Number(latRaw),longitude=lonRaw===''?null:Number(lonRaw);if(latitude!==null&&(!Number.isFinite(latitude)||latitude<-90||latitude>90||!Number.isFinite(longitude)||longitude<-180||longitude>180)){toast('Enter valid latitude and longitude');return}const accuracy=Number(document.getElementById('siteAccuracy').value),obj={id:id||uid(),name,address,rateOverride,latitude,longitude,accuracy:Number.isFinite(accuracy)?accuracy:null,capturedAt:document.getElementById('siteCapturedAt').value||''},i=e.sites.findIndex(s=>s.id===obj.id);if(i>=0)e.sites[i]=obj;else e.sites.push(obj);shifts=shifts.map(s=>s.employerId===empId&&s.siteId===obj.id?{...s,location:obj.name,siteAddress:obj.address,siteLatitude:obj.latitude,siteLongitude:obj.longitude,siteAccuracy:obj.accuracy}:s);scheduled=scheduled.map(s=>s.employerId===empId&&s.siteId===obj.id?{...s,location:obj.name,siteAddress:obj.address,siteLatitude:obj.latitude,siteLongitude:obj.longitude}:s);if(active?.employerId===empId&&active.siteId===obj.id){active.location=obj.name;active.siteAddress=obj.address;active.siteLatitude=obj.latitude;active.siteLongitude=obj.longitude;active.siteAccuracy=obj.accuracy}closeSite();saveAll();toast(i>=0?'Site updated':'Site added')}
function deleteSite(empId,siteId){if(shifts.some(s=>s.employerId===empId&&s.siteId===siteId)||scheduled.some(s=>s.employerId===empId&&s.siteId===siteId)){toast('This site is used by shifts or schedules and cannot be deleted');return}if(!confirm('Delete this saved site?'))return;const e=employerById(empId);if(!e)return;e.sites=e.sites.filter(s=>s.id!==siteId);saveAll();toast('Site deleted')}
function employerCard(e){const sites=(e.sites||[]).length?(e.sites||[]).map(s=>{const gps=s.latitude!==null&&s.longitude!==null?'GPS '+Number(s.latitude).toFixed(5)+', '+Number(s.longitude).toFixed(5):'';return`<div class="site-row"><div><div class="site-name">${esc(s.name)}</div><div class="site-rate">${s.address?esc(s.address)+' • ':''}${s.rateOverride!==null&&s.rateOverride!==''?money(s.rateOverride)+'/hr':'uses '+money(e.defaultRate)+'/hr'}${gps?' • <span class="coord">'+gps+'</span>':''}</div></div><div><button class="mini" onclick="openSite('${e.id}','${s.id}')">Edit</button> <button class="mini" onclick="deleteSite('${e.id}','${s.id}')">Delete</button></div></div>`}).join(''):'<div class="small" style="padding:8px 0">No saved sites.</div>';const payText='Usually paid '+(Number(e.payOffset)===0?'in the same month':Number(e.payOffset)===1?'the following month':'two months later')+' on day '+e.payDay;return`<div class="employer"><div class="employerhead"><div><h3>${esc(e.name)}</h3><div class="meta">Default ${money(e.defaultRate)}/hr${e.payrollRef?' • Ref '+esc(e.payrollRef):''}<br>${esc(payText)}</div></div><div class="actions" style="margin-top:0"><button class="mini" onclick="openEmployer('${e.id}')">Edit</button><button class="mini" onclick="deleteEmployer('${e.id}')">Delete</button></div></div><div class="actions"><button class="mini" onclick="openSite('${e.id}')">＋ Add site</button><button class="mini" onclick="openPayroll('${e.id}','${currentMonth()}','promise')">＋ Payment promise</button></div><div class="site-list">${sites}</div></div>`}
function renderEmployers(){document.getElementById('employerList').innerHTML=employers.length?employers.map(employerCard).join(''):'<div class="empty">No employers yet. Add an employer with its rate, payment schedule and regular work sites.</div>'}

function getPayroll(empId,month,create=false){let p=payrolls.find(x=>x.employerId===empId&&x.earnedMonth===month);if(!p&&create){p={id:uid(),employerId:empId,earnedMonth:month,receipts:[],promises:[],notes:''};payrolls.push(p)}return p||null}
function earnedFor(empId,month){return shifts.filter(s=>s.employerId===empId&&(s.earnedMonth||s.date.slice(0,7))===month).reduce((n,s)=>n+Number(s.total||0),0)}
function receivedFor(empId,month){const p=getPayroll(empId,month,false);return(p?.receipts||[]).reduce((n,r)=>n+Number(r.amount||0),0)}
function remainingFor(empId,month){return Number((earnedFor(empId,month)-receivedFor(empId,month)).toFixed(2))}
function allSalaryMonths(){return [...new Set(shifts.map(s=>s.earnedMonth||String(s.date).slice(0,7)).filter(Boolean).concat(payrolls.map(p=>p.earnedMonth)))].sort()}
function allSalaryRemaining(){return employers.reduce((total,e)=>total+allSalaryMonths().reduce((n,m)=>n+Math.max(0,remainingFor(e.id,m)),0),0)}
function nextPromise(p){return(p?.promises||[]).filter(x=>!x.fulfilled&&x.date).sort((a,b)=>a.date.localeCompare(b.date))[0]||null}
function salaryStatus(empId,month){const earned=earnedFor(empId,month),received=receivedFor(empId,month),remaining=earned-received;if(earned<=0&&received<=0)return'none';if(remaining<=0.005)return'paid';if(received>0)return'partial';return'unpaid'}
function openPayroll(empId,month,mode='receive'){const e=employerById(empId);if(!e)return;const earned=earnedFor(empId,month),received=receivedFor(empId,month),remaining=earned-received;document.getElementById('payrollEmployerId').value=empId;document.getElementById('payrollEarnedMonth').value=month;document.getElementById('payrollModalTitle').textContent=e.name+' — '+monthName(month);document.getElementById('payrollModalSummary').innerHTML='Earned: <strong>'+money(earned)+'</strong><br>Received: <strong>'+money(received)+'</strong><br>Remaining: <strong>'+money(Math.max(0,remaining))+'</strong>';document.getElementById('payReceiptAmount').value=remaining>0?remaining.toFixed(2):'';document.getElementById('payReceiptDate').value=localDate();document.getElementById('payReceiptNote').value='';document.getElementById('payAddNextPromise').checked=false;document.getElementById('nextPromiseFields').classList.add('hidden');document.getElementById('payNextPromiseDate').value='';document.getElementById('payNextPromiseAmount').value='';document.getElementById('payNextPromiseNote').value='';document.getElementById('payPromiseDate').value=expectedPayDate(e,month);document.getElementById('payPromiseAmount').value=remaining>0?remaining.toFixed(2):'';document.getElementById('payPromiseNote').value='';setPayrollModalMode(mode);document.getElementById('payrollModal').classList.add('open')}
function closePayrollModal(){document.getElementById('payrollModal').classList.remove('open')}
function setPayrollModalMode(mode){payrollModalMode=mode;document.getElementById('payReceiveTab').classList.toggle('active',mode==='receive');document.getElementById('payPromiseTab').classList.toggle('active',mode==='promise');document.getElementById('payReceiveSection').classList.toggle('hidden',mode!=='receive');document.getElementById('payPromiseSection').classList.toggle('hidden',mode!=='promise')}
function toggleNextPromise(){document.getElementById('nextPromiseFields').classList.toggle('hidden',!document.getElementById('payAddNextPromise').checked)}
function savePayrollAction(){const empId=document.getElementById('payrollEmployerId').value,month=document.getElementById('payrollEarnedMonth').value,p=getPayroll(empId,month,true);if(payrollModalMode==='receive'){const amount=Number(document.getElementById('payReceiptAmount').value),date=document.getElementById('payReceiptDate').value;if(!(amount>0)||!date){toast('Enter amount received and payment date');return}p.receipts.push({id:uid(),amount:Number(amount.toFixed(2)),date,note:document.getElementById('payReceiptNote').value.trim(),createdAt:new Date().toISOString()});const remaining=earnedFor(empId,month)-p.receipts.reduce((n,r)=>n+Number(r.amount||0),0);if(remaining<=0.005)p.promises.forEach(x=>x.fulfilled=true);if(document.getElementById('payAddNextPromise').checked){const pd=document.getElementById('payNextPromiseDate').value;if(!pd){toast('Enter the next promised date');p.receipts.pop();return}p.promises.push({id:uid(),date:pd,amount:Number(document.getElementById('payNextPromiseAmount').value)||null,note:document.getElementById('payNextPromiseNote').value.trim(),fulfilled:false,createdAt:new Date().toISOString()})}}else{const date=document.getElementById('payPromiseDate').value;if(!date){toast('Enter the promised payment date');return}p.promises.push({id:uid(),date,amount:Number(document.getElementById('payPromiseAmount').value)||null,note:document.getElementById('payPromiseNote').value.trim(),fulfilled:false,createdAt:new Date().toISOString()})}closePayrollModal();saveAll();toast(payrollModalMode==='receive'?'Payment instalment recorded':'Promised payment date saved')}
function openPayrollDetail(empId,month){const e=employerById(empId),p=getPayroll(empId,month,false),earned=earnedFor(empId,month),received=receivedFor(empId,month),remaining=earned-received;document.getElementById('payrollDetailSummary').innerHTML='<strong>'+esc(e?.name||'Employer')+' — '+esc(monthName(month))+'</strong><br>Earned '+money(earned)+' • Received '+money(received)+' • Remaining '+money(Math.max(0,remaining));document.getElementById('payrollReceiptList').innerHTML=(p?.receipts||[]).length?p.receipts.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(r=>`<div class="detail-row"><strong>${money(r.amount)}</strong> received ${niceDate(r.date)}${r.note?'<br>'+esc(r.note):''}<div class="actions"><button class="mini" onclick="deletePayrollReceipt('${p.id}','${r.id}')">Delete</button></div></div>`).join(''):'<div class="empty">No payments received yet.</div>';document.getElementById('payrollPromiseList').innerHTML=(p?.promises||[]).length?p.promises.slice().sort((a,b)=>a.date.localeCompare(b.date)).map(x=>`<div class="detail-row"><strong>${niceDate(x.date)}</strong>${x.amount?' • expected '+money(x.amount):''}<br>${x.fulfilled?'<span class="paidline">Fulfilled</span>':reminderStatus(x.date)==='overdue'?'<span class="overdue">Overdue</span>':'<span class="due">Pending</span>'}${x.note?'<br>'+esc(x.note):''}<div class="actions">${!x.fulfilled?`<button class="mini" onclick="fulfilPromise('${p.id}','${x.id}')">Mark fulfilled</button>`:''}<button class="mini" onclick="deletePayrollPromise('${p.id}','${x.id}')">Delete</button></div></div>`).join(''):'<div class="empty">No promised dates saved.</div>';document.getElementById('payrollDetailModal').classList.add('open')}
function closePayrollDetail(){document.getElementById('payrollDetailModal').classList.remove('open')}
function deletePayrollReceipt(pid,rid){const p=payrolls.find(x=>x.id===pid);if(!p||!confirm('Delete this payment receipt?'))return;p.receipts=p.receipts.filter(x=>x.id!==rid);closePayrollDetail();saveAll();toast('Payment receipt deleted')}
function fulfilPromise(pid,xid){const p=payrolls.find(x=>x.id===pid),x=p?.promises.find(z=>z.id===xid);if(!x)return;x.fulfilled=true;cancelNativeReminder('salary_'+x.id);closePayrollDetail();saveAll();toast('Promise marked fulfilled')}
function deletePayrollPromise(pid,xid){const p=payrolls.find(x=>x.id===pid);if(!p||!confirm('Delete this promised payment date?'))return;p.promises=p.promises.filter(x=>x.id!==xid);cancelNativeReminder('salary_'+xid);closePayrollDetail();saveAll();toast('Promise deleted')}
function payrollCard(e,month){const earned=earnedFor(e.id,month),received=receivedFor(e.id,month),remaining=Number((earned-received).toFixed(2)),p=getPayroll(e.id,month,false),promise=nextPromise(p),status=salaryStatus(e.id,month),percent=earned>0?Math.min(100,Math.max(0,received/earned*100)):0,statusHtml=status==='paid'?'<span class="pill paid">Paid</span>':status==='partial'?'<span class="pill warn">Part paid</span>':status==='unpaid'?'<span class="pill danger">Unpaid</span>':'<span class="pill">No shifts</span>';return`<div class="money-entry"><div class="entryhead"><div><h3>${esc(e.name)}</h3><div class="month-label">Salary earned ${esc(monthName(month))}</div></div>${statusHtml}</div><div class="amount-line"><span>Earned</span><strong>${money(earned)}</strong></div><div class="amount-line"><span>Received</span><strong>${money(received)}</strong></div><div class="progress"><span style="width:${percent}%"></span></div><div class="amount-line"><span>Remaining</span><strong class="${remaining>0?'overdue':'paidline'}">${money(Math.max(0,remaining))}</strong></div><div class="meta" style="margin-top:8px">Normal expected date: ${niceDate(expectedPayDate(e,month))}${promise?'<br>Next promised date: <strong>'+niceDate(promise.date)+'</strong>'+(promise.amount?' • '+money(promise.amount):''):''}</div><div class="actions"><button class="mini" onclick="openPayroll('${e.id}','${month}','receive')">＋ Record payment</button><button class="mini" onclick="openPayroll('${e.id}','${month}','promise')">＋ Promise date</button><button class="mini" onclick="openPayrollDetail('${e.id}','${month}')">History</button></div></div>`}
function showMoneyTab(tab){moneyTab=tab;['salary','diary','received'].forEach(x=>{document.getElementById(x+'Tab').classList.toggle('active',x===tab);document.getElementById(x+'MoneySection').classList.toggle('hidden',x!==tab)});if(tab==='received')renderReceivedReport()}
function renderMoney(){if(!document.getElementById('payrollMonth').value)document.getElementById('payrollMonth').value=currentMonth();if(!document.getElementById('receivedMonth').value)document.getElementById('receivedMonth').value=currentMonth();refreshSelectors();const month=document.getElementById('payrollMonth').value||currentMonth(),choice=document.getElementById('payrollEmployer').value||'all',list=choice==='all'?employers:employers.filter(e=>e.id===choice);document.getElementById('payrollList').innerHTML=list.length?list.map(e=>payrollCard(e,month)).join(''):'<div class="empty">Add an employer first.</div>';const owed=debts.filter(d=>d.direction==='owed_to_me').reduce((n,d)=>n+Math.max(0,debtRemaining(d)),0),iOwe=debts.filter(d=>d.direction==='i_owe').reduce((n,d)=>n+Math.max(0,debtRemaining(d)),0),receivedThis=payrolls.flatMap(p=>(p.receipts||[]).map(r=>({...r,earnedMonth:p.earnedMonth,employerId:p.employerId}))).filter(r=>String(r.date).slice(0,7)===currentMonth()).reduce((n,r)=>n+Number(r.amount||0),0);document.getElementById('moneySalaryRemaining').textContent=money(allSalaryRemaining());document.getElementById('moneyOwedToMe').textContent=money(owed);document.getElementById('moneyIOwe').textContent=money(iOwe);document.getElementById('moneyReceivedMonth').textContent=money(receivedThis);renderDebts();if(moneyTab==='received')renderReceivedReport()}
function renderReceivedReport(){const month=document.getElementById('receivedMonth').value||currentMonth(),rows=[];payrolls.forEach(p=>(p.receipts||[]).forEach(r=>{if(String(r.date).slice(0,7)===month)rows.push({...r,earnedMonth:p.earnedMonth,employerId:p.employerId})}));rows.sort((a,b)=>b.date.localeCompare(a.date));const total=rows.reduce((n,r)=>n+Number(r.amount||0),0);document.getElementById('receivedReportList').innerHTML=rows.length?`<div class="money-entry"><div class="entryhead"><div><h3>Total received ${esc(monthName(month))}</h3><div class="meta">Salary payments received during this month</div></div><div class="money">${money(total)}</div></div></div>`+rows.map(r=>`<div class="money-entry"><div class="entryhead"><div><h3>${esc(employerById(r.employerId)?.name||'Employer')}</h3><div class="meta">Received ${niceDate(r.date)}<br>For salary earned ${esc(monthName(r.earnedMonth))}${r.note?'<br>'+esc(r.note):''}</div></div><div class="money">${money(r.amount)}</div></div></div>`).join(''):'<div class="empty">No salary payments were recorded as received in '+esc(monthName(month))+'.</div>'}

function debtRemaining(d){return Number((Number(d.amount||0)-(d.payments||[]).reduce((n,p)=>n+Number(p.amount||0),0)).toFixed(2))}
function openDebt(id){const d=id?debts.find(x=>x.id===id):null;document.getElementById('debtModalTitle').textContent=d?'Edit personal money record':'Add personal money record';document.getElementById('debtId').value=d?.id||'';document.getElementById('debtPerson').value=d?.person||'';document.getElementById('debtDirection').value=d?.direction||'owed_to_me';document.getElementById('debtAmount').value=d?.amount??'';document.getElementById('debtDueDate').value=d?.dueDate||'';document.getElementById('debtTitle').value=d?.title||'';document.getElementById('debtNotes').value=d?.notes||'';document.getElementById('debtModal').classList.add('open')}
function closeDebt(){document.getElementById('debtModal').classList.remove('open')}
function saveDebt(){const id=document.getElementById('debtId').value||uid(),person=document.getElementById('debtPerson').value.trim(),amount=Number(document.getElementById('debtAmount').value),dueDate=document.getElementById('debtDueDate').value;if(!person||!(amount>0)){toast('Enter person name and total amount');return}const i=debts.findIndex(d=>d.id===id),old=i>=0?debts[i]:null,obj={id,person,direction:document.getElementById('debtDirection').value,amount:Number(amount.toFixed(2)),dueDate,title:document.getElementById('debtTitle').value.trim(),notes:document.getElementById('debtNotes').value.trim(),payments:old?.payments||[],createdAt:old?.createdAt||new Date().toISOString(),status:'open'};if(i>=0)debts[i]=obj;else debts.push(obj);closeDebt();saveAll();toast(i>=0?'Diary record updated':'Diary record added')}
function openDebtPayment(id){const d=debts.find(x=>x.id===id);if(!d)return;document.getElementById('debtPaymentDebtId').value=id;document.getElementById('debtPaymentTitle').textContent=d.direction==='owed_to_me'?'Record money received':'Record money paid';document.getElementById('debtPaymentSummary').innerHTML='<strong>'+esc(d.person)+'</strong><br>'+esc(d.title||'Personal money record')+'<br>Remaining: <strong>'+money(Math.max(0,debtRemaining(d)))+'</strong>';document.getElementById('debtPaymentAmount').value=Math.max(0,debtRemaining(d)).toFixed(2);document.getElementById('debtPaymentDate').value=localDate();document.getElementById('debtPaymentNote').value='';document.getElementById('debtNewDueCheck').checked=false;document.getElementById('debtNewDueWrap').classList.add('hidden');document.getElementById('debtNewDueDate').value='';document.getElementById('debtPaymentModal').classList.add('open')}
function closeDebtPayment(){document.getElementById('debtPaymentModal').classList.remove('open')}
function toggleDebtNextDate(){document.getElementById('debtNewDueWrap').classList.toggle('hidden',!document.getElementById('debtNewDueCheck').checked)}
function saveDebtPayment(){const d=debts.find(x=>x.id===document.getElementById('debtPaymentDebtId').value),amount=Number(document.getElementById('debtPaymentAmount').value),date=document.getElementById('debtPaymentDate').value;if(!d||!(amount>0)||!date){toast('Enter amount and payment date');return}d.payments.push({id:uid(),amount:Number(amount.toFixed(2)),date,note:document.getElementById('debtPaymentNote').value.trim()});if(document.getElementById('debtNewDueCheck').checked){const nd=document.getElementById('debtNewDueDate').value;if(!nd){toast('Enter the new promised date');d.payments.pop();return}d.dueDate=nd}if(debtRemaining(d)<=0.005)d.status='settled';closeDebtPayment();saveAll();toast(d.direction==='owed_to_me'?'Money received recorded':'Payment recorded')}
function deleteDebtPayment(did,pid){const d=debts.find(x=>x.id===did);if(!d||!confirm('Delete this partial payment?'))return;d.payments=d.payments.filter(p=>p.id!==pid);d.status=debtRemaining(d)>0?'open':'settled';saveAll();toast('Partial payment deleted')}
function deleteDebt(id){if(!confirm('Delete this personal money record?'))return;debts=debts.filter(d=>d.id!==id);cancelNativeReminder('debt_'+id);saveAll();toast('Diary record deleted')}
function debtCard(d){const paid=(d.payments||[]).reduce((n,p)=>n+Number(p.amount||0),0),remaining=Math.max(0,debtRemaining(d)),pct=d.amount>0?Math.min(100,paid/d.amount*100):0,due=d.dueDate?reminderStatus(d.dueDate):'',label=d.direction==='owed_to_me'?'They owe me':'I owe them',status=remaining<=0.005?'<span class="pill paid">Settled</span>':due==='overdue'?'<span class="pill danger">Overdue</span>':due==='due'?'<span class="pill warn">Due today</span>':'<span class="pill">Open</span>';const payments=(d.payments||[]).slice().sort((a,b)=>b.date.localeCompare(a.date)).map(p=>`<div class="detail-row"><strong>${money(p.amount)}</strong> • ${niceDate(p.date)}${p.note?' • '+esc(p.note):''} <button class="mini" onclick="deleteDebtPayment('${d.id}','${p.id}')">Delete</button></div>`).join('');return`<div class="money-entry"><div class="entryhead"><div><h3>${esc(d.person)}</h3><div class="meta"><strong>${label}</strong> • ${esc(d.title||'Personal record')}${d.dueDate?'<br>Due / promised '+niceDate(d.dueDate):''}</div></div>${status}</div><div class="amount-line"><span>Total</span><strong>${money(d.amount)}</strong></div><div class="amount-line"><span>Paid / received</span><strong>${money(paid)}</strong></div><div class="progress"><span style="width:${pct}%"></span></div><div class="amount-line"><span>Remaining</span><strong class="${remaining>0?'overdue':'paidline'}">${money(remaining)}</strong></div>${payments?'<div class="divider"></div><div class="detail-list">'+payments+'</div>':''}<div class="actions">${remaining>0?`<button class="mini" onclick="openDebtPayment('${d.id}')">＋ Partial payment</button>`:''}<button class="mini" onclick="openDebt('${d.id}')">Edit</button><button class="mini" onclick="deleteDebt('${d.id}')">Delete</button></div></div>`}
function renderDebts(){const a=[...debts].sort((x,y)=>{const xs=debtRemaining(x)>0?0:1,ys=debtRemaining(y)>0?0:1;return xs-ys||String(x.dueDate||'9999').localeCompare(String(y.dueDate||'9999'))});document.getElementById('debtList').innerHTML=a.length?a.map(debtCard).join(''):'<div class="empty">No personal money records yet.</div>'}

function upcomingReminderItems(){const a=[];scheduled.filter(s=>s.status==='planned').forEach(s=>a.push({type:'shift',date:s.date,time:s.start,title:'Shift: '+employerName(s),text:s.location+' • '+s.start,id:s.id}));payrolls.forEach(p=>(p.promises||[]).filter(x=>!x.fulfilled).forEach(x=>a.push({type:'salary',date:x.date,time:'09:00',title:'Salary payment: '+(employerById(p.employerId)?.name||'Employer'),text:monthName(p.earnedMonth)+(x.amount?' • '+money(x.amount):''),id:x.id})));debts.filter(d=>debtRemaining(d)>0&&d.dueDate).forEach(d=>a.push({type:'debt',date:d.dueDate,time:'09:00',title:d.direction==='owed_to_me'?d.person+' should pay you':'Payment due to '+d.person,text:d.title||'Personal money diary',id:d.id}));return a.sort((x,y)=>(x.date+x.time).localeCompare(y.date+y.time))}
function reminderCard(r){const st=reminderStatus(r.date),pill=st==='overdue'?'<span class="pill danger">Overdue</span>':st==='due'?'<span class="pill warn">Today</span>':'<span class="pill">Upcoming</span>';return`<div class="reminder-entry"><div class="entryhead"><div><h3>${esc(r.title)}</h3><div class="meta">${niceDate(r.date)}${r.type==='shift'?' at '+r.time:''}<br>${esc(r.text)}</div></div>${pill}</div></div>`}
function renderDashboard(){const now=new Date(),today=localDate(now),month=currentMonth(),bounds=monthBounds(month),m=sumRange(bounds.from,today),future=scheduled.filter(s=>s.status==='planned'&&(s.date+s.start)>=today+'00:00').sort((a,b)=>(a.date+a.start).localeCompare(b.date+b.start)),reminders=upcomingReminderItems(),due=reminders.filter(r=>r.date<=today||dateTimeMs(r.date,r.time)<=Date.now()+7*86400000);document.getElementById('monthHours').textContent=hm(m.mins);document.getElementById('monthPay').textContent=money(m.pay)+' earned';document.getElementById('salaryRemaining').textContent=money(allSalaryRemaining());const receivedThis=payrolls.flatMap(p=>p.receipts||[]).filter(r=>String(r.date).slice(0,7)===month).reduce((n,r)=>n+Number(r.amount||0),0);document.getElementById('salaryReceivedMonth').textContent=money(receivedThis)+' received this month';document.getElementById('scheduledCount').textContent=future.length;document.getElementById('nextShiftText').textContent=future[0]?niceDate(future[0].date)+' '+future[0].start:'No future shift';document.getElementById('reminderCount').textContent=due.length;document.getElementById('upcomingShiftList').innerHTML=future.length?future.slice(0,3).map(scheduledCard).join(''):'<div class="empty">No upcoming shifts scheduled.</div>';document.getElementById('dashboardReminderList').innerHTML=reminders.length?reminders.slice(0,3).map(reminderCard).join(''):'<div class="empty">No payment reminders saved.</div>';const recent=[...shifts].sort((x,y)=>(y.date+y.start).localeCompare(x.date+x.start)).slice(0,3);document.getElementById('recentList').innerHTML=recent.length?recent.map(shiftCard).join(''):'<div class="empty">No completed shifts yet.</div>';renderClock()}

function loadProfile(){document.getElementById('pName').value=profile.name||'';document.getElementById('pSia').value=profile.sia||'';document.getElementById('pSiaExpiry').value=profile.siaExpiry||'';document.getElementById('pJob').value=profile.job||'';document.getElementById('pBank').value=profile.bank||'';document.getElementById('pHolder').value=profile.holder||'';document.getElementById('pSort').value=profile.sort||'';document.getElementById('pAccount').value=profile.account||''}
function saveProfile(){profile={...profile,name:document.getElementById('pName').value.trim(),sia:document.getElementById('pSia').value.trim(),siaExpiry:document.getElementById('pSiaExpiry').value,job:document.getElementById('pJob').value.trim(),bank:document.getElementById('pBank').value.trim(),holder:document.getElementById('pHolder').value.trim(),sort:document.getElementById('pSort').value.trim(),account:document.getElementById('pAccount').value.trim()};saveAll();toast('Profile saved')}
function loadSettings(){refreshSelectors();document.getElementById('sEmployer').value=settings.defaultEmployerId||'';document.getElementById('sRole').value=settings.role||profile.job||'Security Officer';refreshBackupStatus();refreshNotificationStatus()}
function saveSettings(){settings={...settings,defaultEmployerId:document.getElementById('sEmployer').value,role:document.getElementById('sRole').value.trim()};saveAll();toast('Defaults saved')}

function defaultDates(){const month=currentMonth(),b=monthBounds(month);if(!document.getElementById('tsMonth').value)document.getElementById('tsMonth').value=month;if(!document.getElementById('tsFrom').value)document.getElementById('tsFrom').value=b.from;if(!document.getElementById('tsTo').value)document.getElementById('tsTo').value=localDate()}
function applyTimesheetMonth(){const m=document.getElementById('tsMonth').value;if(!m)return;const b=monthBounds(m);document.getElementById('tsFrom').value=b.from;document.getElementById('tsTo').value=b.to;renderTimesheet()}
function clearTimesheetMonth(){const f=document.getElementById('tsFrom').value,t=document.getElementById('tsTo').value,m=f.slice(0,7),b=f?monthBounds(m):null;document.getElementById('tsMonth').value=b&&f===b.from&&t===b.to?m:''}
function timesheetShifts(empChoice){defaultDates();const f=document.getElementById('tsFrom').value,t=document.getElementById('tsTo').value;return[...shifts].filter(s=>s.date>=f&&s.date<=t&&(empChoice==='all'||s.employerId===empChoice)).sort((a,b)=>(a.date+a.start).localeCompare(b.date+b.start))}
function summaryGroups(a){const m={};a.forEach(s=>{const id=s.employerId||'unassigned',name=employerName(s);if(!m[id])m[id]={id,name,count:0,mins:0,pay:0};m[id].count++;m[id].mins+=Number(s.paidMinutes||0);m[id].pay+=Number(s.total||0)});return Object.values(m).sort((x,y)=>x.name.localeCompare(y.name))}
function paymentSummaryForShifts(a){const keys=[...new Set(a.map(s=>(s.employerId||'')+'|'+(s.earnedMonth||s.date.slice(0,7))))],rows=[];keys.forEach(k=>{const [empId,month]=k.split('|'),earned=a.filter(s=>s.employerId===empId&&(s.earnedMonth||s.date.slice(0,7))===month).reduce((n,s)=>n+Number(s.total||0),0),received=receivedFor(empId,month);rows.push({employer:employerById(empId)?.name||'Employer',month,earned,received,remaining:Math.max(0,earned-received)})});return rows}
function renderTimesheet(){defaultDates();const choice=document.getElementById('tsEmployer').value||'all',a=timesheetShifts(choice),bank=document.getElementById('includeBank').checked,e=choice==='all'?null:employerById(choice);let info=[];if(profile.name)info.push('<strong>'+esc(profile.name)+'</strong>');if(profile.sia)info.push('SIA: '+esc(profile.sia));info.push('Employer: '+(e?esc(e.name):'All employers combined'));if(e?.payrollRef)info.push('Payroll / employee reference: '+esc(e.payrollRef));info.push('Period: '+niceDate(document.getElementById('tsFrom').value)+' to '+niceDate(document.getElementById('tsTo').value));if(bank){if(profile.bank)info.push('Bank: '+esc(profile.bank));if(profile.holder)info.push('Account holder: '+esc(profile.holder));if(profile.sort)info.push('Sort code: '+esc(profile.sort));if(profile.account)info.push('Account number: '+esc(profile.account))}document.getElementById('tsHeading').textContent=e?'WORK TIMESHEET — '+e.name.toUpperCase():'COMBINED WORK TIMESHEET';document.getElementById('tsProfile').innerHTML=info.join('<br>');document.getElementById('tsRows').innerHTML=a.length?a.map(s=>`<tr><td>${niceDate(s.date)}</td><td>${dayName(s.date)}</td><td>${esc(employerName(s))}</td><td>${esc(s.role||'')}</td><td>${esc(s.location)}</td><td>${s.start}</td><td>${s.end}</td><td>${s.breakMin||0}m</td><td>${decimal(s.paidMinutes)}</td><td>${money(s.rate)}</td><td>${money(s.total)}</td></tr>`).join(''):'<tr><td colspan="11">No shifts in this period.</td></tr>';const mins=a.reduce((n,s)=>n+Number(s.paidMinutes||0),0),breaks=a.reduce((n,s)=>n+Number(s.breakMin||0),0),pay=a.reduce((n,s)=>n+Number(s.total||0),0);document.getElementById('tsFoot').innerHTML=`<tr><td colspan="7">Totals: ${a.length} shifts</td><td>${breaks}m</td><td>${decimal(mins)} h</td><td></td><td>${money(pay)}</td></tr>`;const groups=summaryGroups(a);document.getElementById('tsEmployerSummary').innerHTML=groups.length>1?'<h3 style="margin-top:18px">Employer totals</h3><div class="summary-grid">'+groups.map(g=>`<div class="summary-box"><span class="small">${esc(g.name)} • ${g.count} shifts</span><b>${decimal(g.mins)} h</b><span class="money">${money(g.pay)}</span></div>`).join('')+'</div>':'';const ps=document.getElementById('includePaymentSummary').checked?paymentSummaryForShifts(a):[];document.getElementById('tsPaymentSummary').innerHTML=ps.length?'<h3 style="margin-top:18px">Salary payment summary</h3><div class="detail-list">'+ps.map(x=>`<div class="detail-row"><strong>${esc(x.employer)} — ${esc(monthName(x.month))}</strong><br>Earned ${money(x.earned)} • Received ${money(x.received)} • Remaining ${money(x.remaining)}</div>`).join('')+'</div>':''}
function csvEscape(v){v=String(v??'');return/[",\n]/.test(v)?'"'+v.replace(/"/g,'""')+'"':v}
function csvContent(a,choice){const e=choice==='all'?null:employerById(choice),rows=[['WORK TIMESHEET'],['Name',profile.name||''],['SIA Licence',profile.sia||''],['Employer',e?.name||'All employers combined'],['Period',niceDate(document.getElementById('tsFrom').value)+' to '+niceDate(document.getElementById('tsTo').value)]];if(e?.payrollRef)rows.push(['Payroll / employee reference',e.payrollRef]);if(document.getElementById('includeBank').checked){rows.push(['Bank',profile.bank||'']);rows.push(['Account Holder',profile.holder||'']);rows.push(['Sort Code',profile.sort||'']);rows.push(['Account Number',profile.account||''])}rows.push([]);rows.push(['Date','Day','Employer','Shift','Location','Start Time','End Time','Break Minutes','Paid Hours','Rate Per Hour','Total Payment']);a.forEach(s=>rows.push([niceDate(s.date),dayName(s.date),employerName(s),s.role,s.location,s.start,s.end,s.breakMin,decimal(s.paidMinutes),(Number(s.rate)||0).toFixed(2),(Number(s.total)||0).toFixed(2)]));if(document.getElementById('includePaymentSummary').checked){rows.push([]);rows.push(['SALARY PAYMENT SUMMARY']);paymentSummaryForShifts(a).forEach(x=>rows.push([x.employer,monthName(x.month),'Earned '+x.earned.toFixed(2),'Received '+x.received.toFixed(2),'Remaining '+x.remaining.toFixed(2)]))}rows.push([]);rows.push(['EMPLOYER TOTALS']);summaryGroups(a).forEach(g=>rows.push([g.name,g.count+' shifts',decimal(g.mins)+' hours',(Number(g.pay)||0).toFixed(2)]));const mins=a.reduce((n,s)=>n+Number(s.paidMinutes||0),0),pay=a.reduce((n,s)=>n+Number(s.total||0),0);rows.push(['GRAND TOTAL',a.length+' shifts',decimal(mins)+' hours',(Number(pay)||0).toFixed(2)]);return rows.map(r=>r.map(csvEscape).join(',')).join('\r\n')}
function saveFile(filename,mime,content){if(native()&&AndroidBridge.saveFile)AndroidBridge.saveFile(filename,mime,content);else{const b=new Blob([content],{type:mime}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}}
function safeName(v){return String(v||'User').replace(/[^a-z0-9]+/gi,'_').replace(/^_|_$/g,'')}
function timesheetFilename(choice,suffix='Timesheet'){const e=choice==='all'?'All_Employers':safeName(employerById(choice)?.name||'Employer'),f=document.getElementById('tsFrom').value,t=document.getElementById('tsTo').value;return suffix+'_'+safeName(profile.name||'User')+'_'+e+'_'+f+'_to_'+t}
function saveSelectedCsv(){renderTimesheet();const choice=document.getElementById('tsEmployer').value||'all',a=timesheetShifts(choice);saveFile(timesheetFilename(choice)+'.csv','text/csv',csvContent(a,choice))}
function selectAllAndSave(){document.getElementById('tsEmployer').value='all';renderTimesheet();saveSelectedCsv()}
function saveEmployerSummaryCsv(){const a=timesheetShifts('all'),rows=[['Employer','Number of Shifts','Paid Hours','Total Payment']];summaryGroups(a).forEach(g=>rows.push([g.name,g.count,decimal(g.mins),(Number(g.pay)||0).toFixed(2)]));rows.push(['GRAND TOTAL',a.length,decimal(a.reduce((n,s)=>n+Number(s.paidMinutes||0),0)),a.reduce((n,s)=>n+Number(s.total||0),0).toFixed(2)]);saveFile(timesheetFilename('all','Employer_Totals')+'.csv','text/csv',rows.map(r=>r.map(csvEscape).join(',')).join('\r\n'))}
function printTimesheet(){renderTimesheet();go('timesheet');document.body.classList.add('print-timesheet');setTimeout(()=>{if(native()&&AndroidBridge.printPage)AndroidBridge.printPage();else window.print()},250);setTimeout(()=>document.body.classList.remove('print-timesheet'),6000)}

function scheduleNativeReminder(id,when,title,message){if(native()&&AndroidBridge.scheduleReminder&&Number.isFinite(when)&&when>Date.now()-60000){try{AndroidBridge.scheduleReminder(String(id),Math.round(when),String(title),String(message))}catch(e){}}}
function cancelNativeReminder(id){if(native()&&AndroidBridge.cancelReminder){try{AndroidBridge.cancelReminder(String(id))}catch(e){}}}
function syncAllReminders(show=false){scheduled.filter(s=>s.status==='planned').forEach(s=>scheduleNativeReminder('shift_'+s.id,scheduledReminderMs(s),'Upcoming shift — '+employerName(s),s.location+' at '+s.start));payrolls.forEach(p=>(p.promises||[]).filter(x=>!x.fulfilled&&x.date).forEach(x=>scheduleNativeReminder('salary_'+x.id,dateTimeMs(x.date,'09:00'),'Salary payment reminder',`${employerById(p.employerId)?.name||'Employer'} — ${monthName(p.earnedMonth)}${x.amount?' — '+money(x.amount):''}`)));debts.filter(d=>debtRemaining(d)>0&&d.dueDate).forEach(d=>scheduleNativeReminder('debt_'+d.id,dateTimeMs(d.dueDate,'09:00'),d.direction==='owed_to_me'?'Money due to you':'Payment due',`${d.person} — ${money(debtRemaining(d))} remaining`));if(show)toast('Reminders refreshed')}
function enableNotifications(){if(native()&&AndroidBridge.requestNotificationPermission){AndroidBridge.requestNotificationPermission();setTimeout(()=>{refreshNotificationStatus();syncAllReminders(true)},700)}else{toast('Android notification permission is available in the APK')}}
function refreshNotificationStatus(){const el=document.getElementById('notificationStatus');if(!el)return;let granted=false;if(native()&&AndroidBridge.hasNotificationPermission){try{granted=AndroidBridge.hasNotificationPermission()}catch(e){}}el.innerHTML='<span class="backup-dot '+(granted?'on':'')+'"></span>'+(granted?'Notifications enabled':'Notifications not enabled')}
window.onNotificationPermissionResult=function(granted){refreshNotificationStatus();if(granted){syncAllReminders(true)}else toast('Notification permission was not granted')};

function saveJson(){const stamp=localDate()+'_'+localTime().replace(':','-');saveFile('Job_Buddy_Complete_Backup_'+stamp+'.json','application/json',JSON.stringify(dataBundle(),null,2))}
function connectBackup(){if(native()&&AndroidBridge.connectBackup)AndroidBridge.connectBackup();else toast('Backup connection is available in the Android APK')}
function windowBackupConnected(){refreshBackupStatus();backupNow(true)}window.onBackupFileConnected=windowBackupConnected;
function backupNow(show){if(native()&&AndroidBridge.backup){const ok=AndroidBridge.backup(JSON.stringify(dataBundle()));refreshBackupStatus();if(show)toast(ok?'Backup saved':'Backup failed or is not connected')}else if(show)toast('Connect backup in the Android app')}
function disconnectBackup(){if(native()&&AndroidBridge.disconnectBackup){AndroidBridge.disconnectBackup();refreshBackupStatus();toast('Backup disconnected')}}
function refreshBackupStatus(){let on=false;if(native()&&AndroidBridge.isBackupConnected)on=AndroidBridge.isBackupConnected();const el=document.getElementById('backupStatus');if(el)el.innerHTML='<span class="backup-dot '+(on?'on':'')+'"></span>'+(on?'Connected — automatic backup enabled':'Not connected')}
function updateSiteGpsStatus(message){const el=document.getElementById('siteGpsStatus');if(!el)return;if(message){el.textContent=message;return}const lat=document.getElementById('siteLatitude').value,lon=document.getElementById('siteLongitude').value,acc=Number(document.getElementById('siteAccuracy').value);el.textContent=lat!==''&&lon!==''?'GPS saved: '+Number(lat).toFixed(6)+', '+Number(lon).toFixed(6)+(Number.isFinite(acc)&&acc>0?' • accuracy about '+Math.round(acc)+' metres':''):'No GPS coordinates saved. Location permission is only requested when you press the button.'}
function captureSiteLocation(){updateSiteGpsStatus('Requesting your current location…');if(native()&&AndroidBridge.requestLocation){AndroidBridge.requestLocation();return}beginBrowserLocation()}
function beginBrowserLocation(){if(!navigator.geolocation){updateSiteGpsStatus('Location is not available. Enter coordinates manually.');toast('Location is unavailable');return}navigator.geolocation.getCurrentPosition(pos=>{const lat=Number(pos.coords.latitude),lon=Number(pos.coords.longitude),acc=Number(pos.coords.accuracy);document.getElementById('siteLatitude').value=lat.toFixed(6);document.getElementById('siteLongitude').value=lon.toFixed(6);document.getElementById('siteAccuracy').value=Number.isFinite(acc)?String(Math.round(acc)):'';document.getElementById('siteCapturedAt').value=new Date().toISOString();updateSiteGpsStatus();toast('Live site location added. You can edit it manually.')},err=>{const msg=err&&err.code===1?'Location permission was not granted.':err&&err.code===2?'Your location could not be found.':'Location request timed out.';updateSiteGpsStatus(msg+' You can enter coordinates manually.');toast(msg)},{enableHighAccuracy:true,timeout:20000,maximumAge:0})}
function locationPermissionDenied(){updateSiteGpsStatus('Location permission was not granted. You can enter the address and coordinates manually.');toast('Location permission not granted')}
window.beginBrowserLocation=beginBrowserLocation;window.onLocationPermissionDenied=locationPermissionDenied;
function uploadBackup(){if(native()&&AndroidBridge.openBackup){AndroidBridge.openBackup();return}const input=document.getElementById('backupFileInput');input.value='';input.click()}
function loadBackupInput(event){const file=event.target.files&&event.target.files[0];if(!file)return;const reader=new FileReader();reader.onload=()=>prepareRestore(String(reader.result||''));reader.onerror=()=>toast('Could not read this backup file');reader.readAsText(file)}
function normaliseBackupBundle(raw){const b=clone(raw||{});b.profile=b.profile&&typeof b.profile==='object'?b.profile:{};b.settings=b.settings&&typeof b.settings==='object'?b.settings:{role:'Security Officer'};b.shifts=Array.isArray(b.shifts)?b.shifts:[];b.employers=Array.isArray(b.employers)?b.employers:[];b.active=b.active&&typeof b.active==='object'?b.active:null;b.payrolls=Array.isArray(b.payrolls)?b.payrolls:[];b.scheduled=Array.isArray(b.scheduled)?b.scheduled:[];b.debts=Array.isArray(b.debts)?b.debts:[];if(!b.employers.length&&(b.shifts.length||b.profile.employer||b.settings.location||b.settings.rate)){const eid='restored_'+uid(),siteName=String(b.settings.location||'').trim(),sid=siteName?'restored_site_'+uid():'';const e={id:eid,name:String(b.profile.employer||'Restored Employer').trim(),defaultRate:Number(b.settings.rate)||0,payrollRef:'',payDay:1,payOffset:1,notes:'Restored from an earlier backup',sites:siteName?[{id:sid,name:siteName,address:'',rateOverride:null,latitude:null,longitude:null,accuracy:null,capturedAt:''}]:[]};b.employers=[e];b.settings.defaultEmployerId=eid;b.shifts=b.shifts.map(s=>({...s,employerId:s.employerId||eid,employerName:s.employerName||e.name,siteId:s.siteId||(siteName&&String(s.location||'').toLowerCase()===siteName.toLowerCase()?sid:'')}));if(b.active&&!b.active.employerId)b.active={...b.active,employerId:eid,employerName:e.name}}b.employers.forEach(e=>{e.sites=Array.isArray(e.sites)?e.sites:[];e.payDay=Number(e.payDay)||1;e.payOffset=Number(e.payOffset??1)});return b}
function prepareRestore(text){try{const raw=JSON.parse(String(text).replace(/^\uFEFF/,'')),b=normaliseBackupBundle(raw);if(!raw||typeof raw!=='object'||(!Array.isArray(raw.shifts)&&!Array.isArray(raw.employers)))throw new Error('Invalid');pendingRestore=b;const when=raw.exportedAt?new Date(raw.exportedAt).toLocaleString('en-GB'):'Date not recorded',name=b.profile.name||'Not recorded';document.getElementById('restoreDetails').innerHTML='<strong>'+esc(name)+'</strong><br>Backup date: '+esc(when)+'<br>Employers: '+b.employers.length+'<br>Completed shifts: '+b.shifts.length+'<br>Scheduled shifts: '+b.scheduled.length+'<br>Salary records: '+b.payrolls.length+'<br>Personal diary records: '+b.debts.length+(b.active?'<br>Contains an active clocked-in shift':'');document.getElementById('restoreModal').classList.add('open')}catch(e){pendingRestore=null;toast('This is not a valid Job Buddy or legacy backup')}}
window.onBackupFileLoaded=prepareRestore;
function closeRestore(){pendingRestore=null;document.getElementById('restoreModal').classList.remove('open')}
function mergeUnique(target,source,key='id'){const ids=new Set(target.map(x=>x[key]));source.forEach(x=>{if(!ids.has(x[key]))target.push(clone(x))})}
function applyRestore(mode){if(!pendingRestore)return;const b=normaliseBackupBundle(pendingRestore);if(mode==='replace'){profile=b.profile;settings=b.settings;employers=b.employers;active=b.active;shifts=b.shifts;payrolls=b.payrolls;scheduled=b.scheduled;debts=b.debts}else{const empMap={},siteMap={};b.employers.forEach(be=>{let e=employers.find(x=>x.id===be.id)||employers.find(x=>String(x.name).toLowerCase()===String(be.name).toLowerCase());if(!e){e=clone(be);employers.push(e)}else{e.defaultRate=Number(e.defaultRate)||Number(be.defaultRate)||0;e.payrollRef=e.payrollRef||be.payrollRef||'';e.payDay=e.payDay||be.payDay||1;e.payOffset=e.payOffset??be.payOffset??1;e.notes=e.notes||be.notes||'';if(!Array.isArray(e.sites))e.sites=[];(be.sites||[]).forEach(bs=>{let s=e.sites.find(x=>x.id===bs.id)||e.sites.find(x=>String(x.name).toLowerCase()===String(bs.name).toLowerCase());if(!s){s=clone(bs);e.sites.push(s)}siteMap[(be.id||'')+'|'+(bs.id||'')]=s.id})}empMap[be.id]=e.id});const remap=x=>{const eid=empMap[x.employerId]||x.employerId,e=employerById(eid),sid=siteMap[(x.employerId||'')+'|'+(x.siteId||'')]||x.siteId,s=siteById(e,sid);return{...x,employerId:eid,employerName:e?.name||x.employerName,siteId:sid||'',location:s?.name||x.location,siteAddress:s?.address||x.siteAddress||'',siteLatitude:s?.latitude??x.siteLatitude??null,siteLongitude:s?.longitude??x.siteLongitude??null}};mergeUnique(shifts,b.shifts.map(remap));mergeUnique(scheduled,b.scheduled.map(remap));b.payrolls.forEach(bp=>{const eid=empMap[bp.employerId]||bp.employerId;let p=payrolls.find(x=>x.id===bp.id)||payrolls.find(x=>x.employerId===eid&&x.earnedMonth===bp.earnedMonth);if(!p){p={...clone(bp),employerId:eid};payrolls.push(p)}else{mergeUnique(p.receipts,bp.receipts||[]);mergeUnique(p.promises,bp.promises||[])}});mergeUnique(debts,b.debts);profile={...b.profile,...profile};settings={...b.settings,...settings};if(!active&&b.active)active=remap(b.active)}document.getElementById('restoreModal').classList.remove('open');pendingRestore=null;migrate();renderAll();loadProfile();loadSettings();syncAllReminders(false);backupNow(false);toast(mode==='replace'?'Backup restored — current data replaced':'Backup merged with current records')}
function clearAll(){if(!confirm('Delete all shifts, employers, payment records, reminders, diary records, profile and settings from this phone?'))return;if(!confirm('This cannot be undone unless you have a backup. Continue?'))return;Object.values(K).forEach(k=>localStorage.removeItem(k));shifts=[];employers=[];profile={};active=null;settings={role:'Security Officer'};payrolls=[];scheduled=[];debts=[];renderAll();loadProfile();loadSettings();toast('All local data deleted')}
function renderAll(){refreshSelectors();renderDashboard();renderHistory();renderEmployers();renderTimesheet();renderMoney();refreshBackupStatus();refreshNotificationStatus()}

/* Job Buddy v3.1 — employer-account totals and private imports */
let payrollEditPromise=null;
let payrollEditAdjustment=null;
const salaryMonthLabel=m=>m==='all'?'General / unallocated':monthName(m);
const promiseRange=x=>x?.endDate&&x.endDate!==x.date?niceDate(x.date)+'–'+niceDate(x.endDate):niceDate(x?.date||'');

function migrateV31(){
  payrolls=Array.isArray(payrolls)?payrolls:[];
  payrolls=payrolls.map(p=>({...p,id:p.id||uid(),receipts:Array.isArray(p.receipts)?p.receipts:[],promises:Array.isArray(p.promises)?p.promises:[],adjustments:Array.isArray(p.adjustments)?p.adjustments:[],notes:p.notes||''}));
  persist(false);
}
function dataBundle(){return{app:'Job Buddy',version:'4.5',exportedAt:new Date().toISOString(),profile,settings,employers,active,shifts,payrolls,scheduled,debts}}
function getPayroll(empId,month,create=false){let p=payrolls.find(x=>x.employerId===empId&&x.earnedMonth===month);if(!p&&create){p={id:uid(),employerId:empId,earnedMonth:month,receipts:[],promises:[],adjustments:[],notes:''};payrolls.push(p)}if(p&&!Array.isArray(p.adjustments))p.adjustments=[];return p||null}
function adjustmentFor(empId,month){const p=getPayroll(empId,month,false);return(p?.adjustments||[]).reduce((n,a)=>n+Number(a.amount||0),0)}
function earnedFor(empId,month){
  if(month==='all')return employerAllTimeStats(empId).earned;
  const shiftEarned=shifts.filter(s=>s.employerId===empId&&(s.earnedMonth||s.date.slice(0,7))===month).reduce((n,s)=>n+Number(s.total||0),0);
  return Number((shiftEarned+adjustmentFor(empId,month)).toFixed(2));
}
function receivedFor(empId,month){
  if(month==='all')return Number(payrolls.filter(p=>p.employerId===empId).reduce((n,p)=>n+(p.receipts||[]).reduce((a,r)=>a+Number(r.amount||0),0),0).toFixed(2));
  const p=getPayroll(empId,month,false);return Number((p?.receipts||[]).reduce((n,r)=>n+Number(r.amount||0),0).toFixed(2));
}
function remainingFor(empId,month){return Number((earnedFor(empId,month)-receivedFor(empId,month)).toFixed(2))}
function allSalaryMonths(){return[...new Set(shifts.map(s=>s.earnedMonth||String(s.date).slice(0,7)).filter(Boolean).concat(payrolls.map(p=>p.earnedMonth).filter(m=>m&&m!=='all')))].sort()}
function employerAllTimeStats(empId){
  const ss=shifts.filter(s=>s.employerId===empId),shiftEarned=ss.reduce((n,s)=>n+Number(s.total||0),0),adjustments=payrolls.filter(p=>p.employerId===empId).reduce((n,p)=>n+(p.adjustments||[]).reduce((a,x)=>a+Number(x.amount||0),0),0),received=payrolls.filter(p=>p.employerId===empId).reduce((n,p)=>n+(p.receipts||[]).reduce((a,x)=>a+Number(x.amount||0),0),0),mins=ss.reduce((n,s)=>n+Number(s.paidMinutes||0),0),earned=Number((shiftEarned+adjustments).toFixed(2));
  return{empId,shifts:ss.length,mins,shiftEarned:Number(shiftEarned.toFixed(2)),adjustments:Number(adjustments.toFixed(2)),earned,received:Number(received.toFixed(2)),remaining:Number((earned-received).toFixed(2))}
}
function allSalaryEarned(){return Number(employers.reduce((n,e)=>n+employerAllTimeStats(e.id).earned,0).toFixed(2))}
function allSalaryRemaining(){return Number(employers.reduce((n,e)=>n+Math.max(0,employerAllTimeStats(e.id).remaining),0).toFixed(2))}
function employerPromises(empId){return payrolls.filter(p=>p.employerId===empId).flatMap(p=>(p.promises||[]).map(x=>({...x,payrollId:p.id,earnedMonth:p.earnedMonth}))).filter(x=>!x.fulfilled&&x.date).sort((a,b)=>a.date.localeCompare(b.date))}
function salaryStatus(empId,month){const earned=earnedFor(empId,month),received=receivedFor(empId,month),remaining=earned-received;if(earned<=0&&received<=0)return'none';if(remaining<=0.005)return'paid';if(received>0)return'partial';return'unpaid'}
function monthBreakdown(empId){return allSalaryMonths().filter(m=>earnedFor(empId,m)!==0||receivedFor(empId,m)!==0||getPayroll(empId,m,false)).map(m=>({month:m,earned:earnedFor(empId,m),received:receivedFor(empId,m),remaining:remainingFor(empId,m)}))}

function openPayroll(empId,month,mode='receive'){
  const e=employerById(empId);if(!e)return;const stats=month==='all'?employerAllTimeStats(empId):null,earned=month==='all'?stats.earned:earnedFor(empId,month),received=month==='all'?stats.received:receivedFor(empId,month),remaining=earned-received;
  payrollEditPromise=null;payrollEditAdjustment=null;
  document.getElementById('payrollEmployerId').value=empId;document.getElementById('payrollEarnedMonth').value=month;
  document.getElementById('payrollModalTitle').textContent=e.name+' — '+salaryMonthLabel(month);
  document.getElementById('payrollModalSummary').innerHTML='Earned: <strong>'+money(earned)+'</strong><br>Received: <strong>'+money(received)+'</strong><br>Remaining: <strong>'+money(Math.max(0,remaining))+'</strong>'+(month==='all'?'<br><span class="small">Payments saved here are general employer payments and are not assigned to one salary month.</span>':'');
  document.getElementById('payReceiptAmount').value=remaining>0?remaining.toFixed(2):'';document.getElementById('payReceiptDate').value=localDate();document.getElementById('payReceiptNote').value='';document.getElementById('payAddNextPromise').checked=false;document.getElementById('nextPromiseFields').classList.add('hidden');document.getElementById('payNextPromiseDate').value='';document.getElementById('payNextPromiseAmount').value='';document.getElementById('payNextPromiseNote').value='';
  document.getElementById('payPromiseDate').value=month==='all'?localDate():expectedPayDate(e,month);document.getElementById('payPromiseEndDate').value='';document.getElementById('payPromiseAmount').value=remaining>0?remaining.toFixed(2):'';document.getElementById('payPromiseNote').value='';
  document.getElementById('payAdjustmentMonth').value=month==='all'?currentMonth():month;document.getElementById('payAdjustmentAmount').value='';document.getElementById('payAdjustmentDate').value=localDate();document.getElementById('payAdjustmentNote').value='';
  setPayrollModalMode(mode);document.getElementById('payrollModal').classList.add('open')
}
function closePayrollModal(){payrollEditPromise=null;payrollEditAdjustment=null;document.getElementById('payrollModal').classList.remove('open')}
function setPayrollModalMode(mode){payrollModalMode=mode;['receive','promise','adjustment'].forEach(x=>{const cap=x[0].toUpperCase()+x.slice(1);document.getElementById('pay'+cap+'Tab')?.classList.toggle('active',mode===x);document.getElementById('pay'+cap+'Section')?.classList.toggle('hidden',mode!==x)})}
function savePayrollAction(){
  const empId=document.getElementById('payrollEmployerId').value,month=document.getElementById('payrollEarnedMonth').value;
  if(payrollModalMode==='adjustment'){
    const am=document.getElementById('payAdjustmentMonth').value,amount=Number(document.getElementById('payAdjustmentAmount').value),date=document.getElementById('payAdjustmentDate').value,note=document.getElementById('payAdjustmentNote').value.trim();if(!am||!Number.isFinite(amount)||amount===0||!date){toast('Enter salary month, non-zero amount and adjustment date');return}const p=getPayroll(empId,am,true),obj={id:payrollEditAdjustment?.id||uid(),amount:Number(amount.toFixed(2)),date,note,createdAt:payrollEditAdjustment?.createdAt||new Date().toISOString()};if(payrollEditAdjustment){const i=p.adjustments.findIndex(x=>x.id===obj.id);if(i>=0)p.adjustments[i]=obj;else p.adjustments.push(obj)}else p.adjustments.push(obj);closePayrollModal();saveAll();toast('Salary balance adjustment saved');return
  }
  const p=getPayroll(empId,month,true);
  if(payrollModalMode==='receive'){
    const amount=Number(document.getElementById('payReceiptAmount').value),date=document.getElementById('payReceiptDate').value;if(!(amount>0)||!date){toast('Enter amount received and payment date');return}p.receipts.push({id:uid(),amount:Number(amount.toFixed(2)),date,note:document.getElementById('payReceiptNote').value.trim(),createdAt:new Date().toISOString()});const remaining=remainingFor(empId,month);if(remaining<=0.005&&month!=='all')p.promises.forEach(x=>x.fulfilled=true);if(document.getElementById('payAddNextPromise').checked){const pd=document.getElementById('payNextPromiseDate').value;if(!pd){toast('Enter the next promised date');p.receipts.pop();return}p.promises.push({id:uid(),date:pd,endDate:'',amount:Number(document.getElementById('payNextPromiseAmount').value)||null,note:document.getElementById('payNextPromiseNote').value.trim(),fulfilled:false,createdAt:new Date().toISOString()})}
  }else{
    const date=document.getElementById('payPromiseDate').value,endDate=document.getElementById('payPromiseEndDate').value;if(!date){toast('Enter the promised payment date');return}if(endDate&&endDate<date){toast('Latest promised date cannot be earlier than the first date');return}const obj={id:payrollEditPromise?.id||uid(),date,endDate,amount:Number(document.getElementById('payPromiseAmount').value)||null,note:document.getElementById('payPromiseNote').value.trim(),fulfilled:payrollEditPromise?.fulfilled||false,createdAt:payrollEditPromise?.createdAt||new Date().toISOString()};if(payrollEditPromise){const i=p.promises.findIndex(x=>x.id===obj.id);if(i>=0)p.promises[i]=obj;else p.promises.push(obj)}else p.promises.push(obj)
  }
  closePayrollModal();saveAll();toast(payrollModalMode==='receive'?'Payment instalment recorded':'Promised payment date saved')
}
function editPayrollPromise(pid,xid){const p=payrolls.find(x=>x.id===pid),x=p?.promises.find(z=>z.id===xid);if(!p||!x)return;openPayroll(p.employerId,p.earnedMonth,'promise');payrollEditPromise={...x};document.getElementById('payPromiseDate').value=x.date||'';document.getElementById('payPromiseEndDate').value=x.endDate||'';document.getElementById('payPromiseAmount').value=x.amount??'';document.getElementById('payPromiseNote').value=x.note||''}
function editPayrollAdjustment(pid,aid){const p=payrolls.find(x=>x.id===pid),a=p?.adjustments?.find(z=>z.id===aid);if(!p||!a)return;openPayroll(p.employerId,p.earnedMonth,'adjustment');payrollEditAdjustment={...a};document.getElementById('payAdjustmentMonth').value=p.earnedMonth;document.getElementById('payAdjustmentAmount').value=a.amount;document.getElementById('payAdjustmentDate').value=a.date||localDate();document.getElementById('payAdjustmentNote').value=a.note||''}
function deletePayrollAdjustment(pid,aid){const p=payrolls.find(x=>x.id===pid);if(!p||!confirm('Delete this salary adjustment?'))return;p.adjustments=(p.adjustments||[]).filter(x=>x.id!==aid);closePayrollDetail();saveAll();toast('Salary adjustment deleted')}
function openPayrollDetail(empId,month){
  const e=employerById(empId),records=month==='all'?payrolls.filter(p=>p.employerId===empId):[getPayroll(empId,month,false)].filter(Boolean),earned=earnedFor(empId,month),received=receivedFor(empId,month),remaining=earned-received;
  document.getElementById('payrollDetailSummary').innerHTML='<strong>'+esc(e?.name||'Employer')+' — '+esc(salaryMonthLabel(month))+'</strong><br>Earned '+money(earned)+' • Received '+money(received)+' • Remaining '+money(Math.max(0,remaining));
  const adjustments=records.flatMap(p=>(p.adjustments||[]).map(a=>({...a,pid:p.id,month:p.earnedMonth}))).sort((a,b)=>(b.date||'').localeCompare(a.date||''));
  const receipts=records.flatMap(p=>(p.receipts||[]).map(r=>({...r,pid:p.id,month:p.earnedMonth}))).sort((a,b)=>b.date.localeCompare(a.date));
  const promises=records.flatMap(p=>(p.promises||[]).map(x=>({...x,pid:p.id,month:p.earnedMonth}))).sort((a,b)=>a.date.localeCompare(b.date));
  document.getElementById('payrollAdjustmentList').innerHTML=adjustments.length?adjustments.map(a=>`<div class="detail-row"><strong>${a.amount>=0?'+':''}${money(a.amount)}</strong> • ${esc(salaryMonthLabel(a.month))} • ${niceDate(a.date)}${a.note?'<br>'+esc(a.note):''}<div class="actions"><button class="mini" onclick="editPayrollAdjustment('${a.pid}','${a.id}')">Edit</button><button class="mini" onclick="deletePayrollAdjustment('${a.pid}','${a.id}')">Delete</button></div></div>`).join(''):'<div class="empty">No opening balances or salary adjustments.</div>';
  document.getElementById('payrollReceiptList').innerHTML=receipts.length?receipts.map(r=>`<div class="detail-row"><strong>${money(r.amount)}</strong> received ${niceDate(r.date)} • ${esc(salaryMonthLabel(r.month))}${r.note?'<br>'+esc(r.note):''}<div class="actions"><button class="mini" onclick="deletePayrollReceipt('${r.pid}','${r.id}')">Delete</button></div></div>`).join(''):'<div class="empty">No payments received yet.</div>';
  document.getElementById('payrollPromiseList').innerHTML=promises.length?promises.map(x=>`<div class="detail-row"><strong>${promiseRange(x)}</strong> • ${esc(salaryMonthLabel(x.month))}${x.amount?' • expected '+money(x.amount):''}<br>${x.fulfilled?'<span class="paidline">Fulfilled</span>':reminderStatus(x.date)==='overdue'?'<span class="overdue">Overdue</span>':'<span class="due">Pending</span>'}${x.note?'<br>'+esc(x.note):''}<div class="actions">${!x.fulfilled?`<button class="mini" onclick="fulfilPromise('${x.pid}','${x.id}')">Mark fulfilled</button>`:''}<button class="mini" onclick="editPayrollPromise('${x.pid}','${x.id}')">Edit</button><button class="mini" onclick="deletePayrollPromise('${x.pid}','${x.id}')">Delete</button></div></div>`).join(''):'<div class="empty">No promised dates saved.</div>';
  document.getElementById('payrollDetailModal').classList.add('open')
}
function payrollCard(e,month){const earned=earnedFor(e.id,month),received=receivedFor(e.id,month),remaining=Number((earned-received).toFixed(2)),p=getPayroll(e.id,month,false),promise=nextPromise(p),status=salaryStatus(e.id,month),percent=earned>0?Math.min(100,Math.max(0,received/earned*100)):0,statusHtml=status==='paid'?'<span class="pill paid">Paid</span>':status==='partial'?'<span class="pill warn">Part paid</span>':status==='unpaid'?'<span class="pill danger">Unpaid</span>':'<span class="pill">No shifts</span>';return`<div class="money-entry"><div class="entryhead"><div><h3>${esc(e.name)}</h3><div class="month-label">Salary earned ${esc(monthName(month))}</div></div>${statusHtml}</div><div class="amount-line"><span>Earned</span><strong>${money(earned)}</strong></div><div class="amount-line"><span>Received for this month</span><strong>${money(received)}</strong></div><div class="progress"><span style="width:${percent}%"></span></div><div class="amount-line"><span>Remaining for this month</span><strong class="${remaining>0?'overdue':'paidline'}">${money(Math.max(0,remaining))}</strong></div><div class="meta" style="margin-top:8px">Normal expected date: ${niceDate(expectedPayDate(e,month))}${promise?'<br>Next promised date: <strong>'+promiseRange(promise)+'</strong>'+(promise.amount?' • '+money(promise.amount):''):''}${receivedFor(e.id,'all')>received?'<br>Employer also has general/unallocated payments in the all-time account.':''}</div><div class="actions"><button class="mini" onclick="openPayroll('${e.id}','${month}','receive')">＋ Month payment</button><button class="mini" onclick="openPayroll('${e.id}','${month}','promise')">＋ Promise</button><button class="mini" onclick="openPayroll('${e.id}','${month}','adjustment')">＋ Adjustment</button><button class="mini" onclick="openPayrollDetail('${e.id}','${month}')">History</button></div></div>`}
function employerAccountCard(e){
  const s=employerAllTimeStats(e.id),promises=employerPromises(e.id),promise=promises[0],percent=s.earned>0?Math.min(100,Math.max(0,s.received/s.earned*100)):0,months=monthBreakdown(e.id),status=s.remaining<=0.005&&s.earned>0?'<span class="pill paid">Paid</span>':s.received>0?'<span class="pill warn">Part paid</span>':'<span class="pill danger">Unpaid</span>';
  const monthly=months.length?'<div class="detail-list" style="margin-top:12px">'+months.map(m=>`<div class="detail-row"><strong>${esc(monthName(m.month))}</strong><br>${money(m.earned)} earned • ${money(m.received)} allocated received • ${money(Math.max(0,m.remaining))} remaining</div>`).join('')+'</div>':'<div class="small" style="margin-top:10px">No salary months yet.</div>';
  return`<div class="money-entry"><div class="entryhead"><div><h3>${esc(e.name)}</h3><div class="month-label">Complete employer account • ${s.shifts} shifts • ${decimal(s.mins)} hours</div></div>${status}</div><div class="amount-line"><span>Total earned</span><strong>${money(s.earned)}</strong></div><div class="amount-line"><span>Total received</span><strong>${money(s.received)}</strong></div><div class="progress"><span style="width:${percent}%"></span></div><div class="amount-line"><span>Total remaining</span><strong class="${s.remaining>0?'overdue':'paidline'}">${money(Math.max(0,s.remaining))}</strong></div>${s.adjustments?`<div class="meta">Includes salary adjustments/opening balances: ${money(s.adjustments)}</div>`:''}${promise?`<div class="meta" style="margin-top:8px">Next promised payment: <strong>${promiseRange(promise)}</strong>${promise.amount?' • '+money(promise.amount):''}<br>${esc(salaryMonthLabel(promise.earnedMonth))}</div>`:''}${monthly}<div class="actions"><button class="mini" onclick="openPayroll('${e.id}','all','receive')">＋ General payment</button><button class="mini" onclick="openPayroll('${e.id}','all','promise')">＋ General promise</button><button class="mini" onclick="openPayroll('${e.id}','all','adjustment')">＋ Opening balance</button><button class="mini" onclick="openPayrollDetail('${e.id}','all')">Full history</button></div></div>`
}
function renderMoney(){
  if(!document.getElementById('payrollMonth').value)document.getElementById('payrollMonth').value=currentMonth();if(!document.getElementById('receivedMonth').value)document.getElementById('receivedMonth').value=currentMonth();refreshSelectors();
  const scope=document.getElementById('payrollScope')?.value||'alltime',wrap=document.getElementById('payrollMonthWrap');wrap?.classList.toggle('hidden',scope!=='month');const notice=document.getElementById('payrollScopeNotice');if(notice)notice.innerHTML=scope==='month'?'Selected-month view keeps salary with the month it was earned. General payments remain visible in the employer all-time account.':'All-time view combines every shift, salary adjustment, payment instalment, promise and remaining balance for each employer.';
  const month=document.getElementById('payrollMonth').value||currentMonth(),choice=document.getElementById('payrollEmployer').value||'all',list=choice==='all'?employers:employers.filter(e=>e.id===choice);document.getElementById('payrollList').innerHTML=list.length?list.map(e=>scope==='month'?payrollCard(e,month):employerAccountCard(e)).join(''):'<div class="empty">Add an employer first.</div>';
  const owed=debts.filter(d=>d.direction==='owed_to_me').reduce((n,d)=>n+Math.max(0,debtRemaining(d)),0),iOwe=debts.filter(d=>d.direction==='i_owe').reduce((n,d)=>n+Math.max(0,debtRemaining(d)),0),receivedThis=payrolls.flatMap(p=>(p.receipts||[]).map(r=>({...r,earnedMonth:p.earnedMonth,employerId:p.employerId}))).filter(r=>String(r.date).slice(0,7)===currentMonth()).reduce((n,r)=>n+Number(r.amount||0),0);document.getElementById('moneySalaryEarned').textContent=money(allSalaryEarned());document.getElementById('moneySalaryRemaining').textContent=money(allSalaryRemaining());document.getElementById('moneyOwedToMe').textContent=money(owed);document.getElementById('moneyIOwe').textContent=money(iOwe);document.getElementById('moneyReceivedMonth').textContent=money(receivedThis);renderDebts();if(moneyTab==='received')renderReceivedReport()
}
function renderReceivedReport(){const month=document.getElementById('receivedMonth').value||currentMonth(),rows=[];payrolls.forEach(p=>(p.receipts||[]).forEach(r=>{if(String(r.date).slice(0,7)===month)rows.push({...r,earnedMonth:p.earnedMonth,employerId:p.employerId})}));rows.sort((a,b)=>b.date.localeCompare(a.date));const total=rows.reduce((n,r)=>n+Number(r.amount||0),0);document.getElementById('receivedReportList').innerHTML=rows.length?`<div class="money-entry"><div class="entryhead"><div><h3>Total received ${esc(monthName(month))}</h3><div class="meta">Salary payments received during this month</div></div><div class="money">${money(total)}</div></div></div>`+rows.map(r=>`<div class="money-entry"><div class="entryhead"><div><h3>${esc(employerById(r.employerId)?.name||'Employer')}</h3><div class="meta">Received ${niceDate(r.date)}<br>Allocated to: ${esc(salaryMonthLabel(r.earnedMonth))}${r.note?'<br>'+esc(r.note):''}</div></div><div class="money">${money(r.amount)}</div></div></div>`).join(''):'<div class="empty">No salary payments were recorded as received in '+esc(monthName(month))+'.</div>'}

function toggleAllTimeTimesheet(){const on=document.getElementById('tsAllTime').checked;document.getElementById('tsMonth').disabled=on;document.getElementById('tsFrom').disabled=on;document.getElementById('tsTo').disabled=on;renderTimesheet()}
function applyTimesheetMonth(){document.getElementById('tsAllTime').checked=false;toggleAllTimeTimesheet();const m=document.getElementById('tsMonth').value;if(!m)return;const b=monthBounds(m);document.getElementById('tsFrom').value=b.from;document.getElementById('tsTo').value=b.to;renderTimesheet()}
function timesheetShifts(empChoice){defaultDates();const all=document.getElementById('tsAllTime')?.checked,f=document.getElementById('tsFrom').value,t=document.getElementById('tsTo').value;return[...shifts].filter(s=>(all||(s.date>=f&&s.date<=t))&&(empChoice==='all'||s.employerId===empChoice)).sort((a,b)=>(a.date+a.start).localeCompare(b.date+b.start))}
function accountGroups(choice){const list=choice==='all'?employers:employers.filter(e=>e.id===choice);return list.map(e=>({name:e.name,...employerAllTimeStats(e.id)})).filter(x=>x.earned||x.received||x.shifts)}
function renderTimesheet(){
  defaultDates();const choice=document.getElementById('tsEmployer').value||'all',a=timesheetShifts(choice),bank=document.getElementById('includeBank').checked,e=choice==='all'?null:employerById(choice),all=document.getElementById('tsAllTime')?.checked;let info=[];if(profile.name)info.push('<strong>'+esc(profile.name)+'</strong>');if(profile.sia)info.push('SIA: '+esc(profile.sia));info.push('Employer: '+(e?esc(e.name):'All employers combined'));if(e?.payrollRef)info.push('Payroll / employee reference: '+esc(e.payrollRef));info.push('Period: '+(all?'All records to date':niceDate(document.getElementById('tsFrom').value)+' to '+niceDate(document.getElementById('tsTo').value)));if(bank){if(profile.bank)info.push('Bank: '+esc(profile.bank));if(profile.holder)info.push('Account holder: '+esc(profile.holder));if(profile.sort)info.push('Sort code: '+esc(profile.sort));if(profile.account)info.push('Account number: '+esc(profile.account))}document.getElementById('tsHeading').textContent=e?'WORK TIMESHEET — '+e.name.toUpperCase():'COMBINED WORK TIMESHEET';document.getElementById('tsProfile').innerHTML=info.join('<br>');document.getElementById('tsRows').innerHTML=a.length?a.map(s=>`<tr><td>${niceDate(s.date)}</td><td>${dayName(s.date)}</td><td>${esc(employerName(s))}</td><td>${esc(s.role||'')}</td><td>${esc(s.location)}</td><td>${s.start}</td><td>${s.end}</td><td>${s.breakMin||0}m</td><td>${decimal(s.paidMinutes)}</td><td>${money(s.rate)}</td><td>${money(s.total)}</td></tr>`).join(''):'<tr><td colspan="11">No shifts in this period.</td></tr>';const mins=a.reduce((n,s)=>n+Number(s.paidMinutes||0),0),breaks=a.reduce((n,s)=>n+Number(s.breakMin||0),0),pay=a.reduce((n,s)=>n+Number(s.total||0),0);document.getElementById('tsFoot').innerHTML=`<tr><td colspan="7">Totals: ${a.length} shifts</td><td>${breaks}m</td><td>${decimal(mins)} h</td><td></td><td>${money(pay)}</td></tr>`;
  const ps=document.getElementById('includePaymentSummary').checked?paymentSummaryForShifts(a):[];document.getElementById('tsPaymentSummary').innerHTML=ps.length?'<h3 style="margin-top:18px">Selected salary-month summary</h3><div class="detail-list">'+ps.map(x=>`<div class="detail-row"><strong>${esc(x.employer)} — ${esc(monthName(x.month))}</strong><br>Earned ${money(x.earned)} • Allocated received ${money(x.received)} • Remaining ${money(x.remaining)}</div>`).join('')+'</div>':'';
  const ag=accountGroups(choice),grand=ag.reduce((o,x)=>({earned:o.earned+x.earned,received:o.received+x.received,remaining:o.remaining+Math.max(0,x.remaining)}),{earned:0,received:0,remaining:0});document.getElementById('tsEmployerSummary').innerHTML=ag.length?'<h3 style="margin-top:18px">Employer account totals — all records</h3><div class="summary-grid">'+ag.map(g=>`<div class="summary-box"><span class="small">${esc(g.name)} • ${g.shifts} shifts • ${decimal(g.mins)} h</span><b>${money(g.earned)} earned</b><span>${money(g.received)} received</span><span class="money">${money(Math.max(0,g.remaining))} remaining</span></div>`).join('')+'</div>'+(ag.length>1?`<div class="restore-detail" style="margin-top:12px"><strong>All employers together</strong><br>Earned ${money(grand.earned)} • Received ${money(grand.received)} • Remaining ${money(grand.remaining)}</div>`:''):''
}
function csvContent(a,choice){const e=choice==='all'?null:employerById(choice),all=document.getElementById('tsAllTime')?.checked,rows=[['WORK TIMESHEET'],['Name',profile.name||''],['SIA Licence',profile.sia||''],['Employer',e?.name||'All employers combined'],['Period',all?'All records to date':niceDate(document.getElementById('tsFrom').value)+' to '+niceDate(document.getElementById('tsTo').value)]];if(e?.payrollRef)rows.push(['Payroll / employee reference',e.payrollRef]);if(document.getElementById('includeBank').checked){rows.push(['Bank',profile.bank||'']);rows.push(['Account Holder',profile.holder||'']);rows.push(['Sort Code',profile.sort||'']);rows.push(['Account Number',profile.account||''])}rows.push([]);rows.push(['Date','Day','Employer','Shift','Location','Start Time','End Time','Break Minutes','Paid Hours','Rate Per Hour','Total Payment']);a.forEach(s=>rows.push([niceDate(s.date),dayName(s.date),employerName(s),s.role,s.location,s.start,s.end,s.breakMin,decimal(s.paidMinutes),(Number(s.rate)||0).toFixed(2),(Number(s.total)||0).toFixed(2)]));if(document.getElementById('includePaymentSummary').checked){rows.push([]);rows.push(['SELECTED SALARY-MONTH SUMMARY']);paymentSummaryForShifts(a).forEach(x=>rows.push([x.employer,monthName(x.month),'Earned '+x.earned.toFixed(2),'Allocated received '+x.received.toFixed(2),'Remaining '+x.remaining.toFixed(2)]))}rows.push([]);rows.push(['EMPLOYER ACCOUNT TOTALS — ALL RECORDS']);accountGroups(choice).forEach(g=>rows.push([g.name,g.shifts+' shifts',decimal(g.mins)+' hours','Earned '+g.earned.toFixed(2),'Received '+g.received.toFixed(2),'Remaining '+Math.max(0,g.remaining).toFixed(2)]));const mins=a.reduce((n,s)=>n+Number(s.paidMinutes||0),0),pay=a.reduce((n,s)=>n+Number(s.total||0),0);rows.push([]);rows.push(['SELECTED SHIFT TOTAL',a.length+' shifts',decimal(mins)+' hours',(Number(pay)||0).toFixed(2)]);return rows.map(r=>r.map(csvEscape).join(',')).join('\r\n')}
function timesheetFilename(choice,suffix='Timesheet'){const e=choice==='all'?'All_Employers':safeName(employerById(choice)?.name||'Employer'),all=document.getElementById('tsAllTime')?.checked,f=all?'All_Records':document.getElementById('tsFrom').value,t=all?'To_Date':document.getElementById('tsTo').value;return suffix+'_'+safeName(profile.name||'User')+'_'+e+'_'+f+(all?'':'_to_')+t}
function saveEmployerSummaryCsv(){const a=timesheetShifts('all'),rows=[['Employer','Number of Shifts','Paid Hours','Earned in Selected Period']];summaryGroups(a).forEach(g=>rows.push([g.name,g.count,decimal(g.mins),(Number(g.pay)||0).toFixed(2)]));rows.push(['GRAND TOTAL',a.length,decimal(a.reduce((n,s)=>n+Number(s.paidMinutes||0),0)),a.reduce((n,s)=>n+Number(s.total||0),0).toFixed(2)]);saveFile(timesheetFilename('all','Period_Employer_Totals')+'.csv','text/csv',rows.map(r=>r.map(csvEscape).join(',')).join('\r\n'))}
function saveEmployerAccountCsv(){const choice=document.getElementById('tsEmployer').value||'all',rows=[['EMPLOYER ACCOUNT — ALL RECORDS'],['Name',profile.name||''],['Generated',new Date().toLocaleString('en-GB')],[],['Employer','Shifts','Hours','Shift Earnings','Adjustments / Opening Balances','Total Earned','Total Received','Remaining']];accountGroups(choice).forEach(g=>rows.push([g.name,g.shifts,decimal(g.mins),g.shiftEarned.toFixed(2),g.adjustments.toFixed(2),g.earned.toFixed(2),g.received.toFixed(2),Math.max(0,g.remaining).toFixed(2)]));const gs=accountGroups(choice).reduce((o,g)=>({shifts:o.shifts+g.shifts,mins:o.mins+g.mins,shiftEarned:o.shiftEarned+g.shiftEarned,adjustments:o.adjustments+g.adjustments,earned:o.earned+g.earned,received:o.received+g.received,remaining:o.remaining+Math.max(0,g.remaining)}),{shifts:0,mins:0,shiftEarned:0,adjustments:0,earned:0,received:0,remaining:0});rows.push(['ALL TOGETHER',gs.shifts,decimal(gs.mins),gs.shiftEarned.toFixed(2),gs.adjustments.toFixed(2),gs.earned.toFixed(2),gs.received.toFixed(2),gs.remaining.toFixed(2)]);saveFile('Employer_Account_'+safeName(profile.name||'User')+'_'+(choice==='all'?'All_Employers':safeName(employerById(choice)?.name))+'_All_Records.csv','text/csv',rows.map(r=>r.map(csvEscape).join(',')).join('\r\n'))}

function upcomingReminderItems(){const a=[];scheduled.filter(s=>s.status==='planned').forEach(s=>a.push({type:'shift',date:s.date,time:s.start,title:'Shift: '+employerName(s),text:s.location+' • '+s.start,id:s.id}));payrolls.forEach(p=>(p.promises||[]).filter(x=>!x.fulfilled).forEach(x=>a.push({type:'salary',date:x.date,time:'09:00',title:'Salary payment: '+(employerById(p.employerId)?.name||'Employer'),text:salaryMonthLabel(p.earnedMonth)+(x.amount?' • '+money(x.amount):'')+(x.endDate?' • by '+niceDate(x.endDate):''),id:x.id})));debts.filter(d=>debtRemaining(d)>0&&d.dueDate).forEach(d=>a.push({type:'debt',date:d.dueDate,time:'09:00',title:d.direction==='owed_to_me'?d.person+' should pay you':'Payment due to '+d.person,text:d.title||'Personal money diary',id:d.id}));return a.sort((x,y)=>(x.date+x.time).localeCompare(y.date+y.time))}
function syncAllReminders(show=false){scheduled.filter(s=>s.status==='planned').forEach(s=>scheduleNativeReminder('shift_'+s.id,scheduledReminderMs(s),'Upcoming shift — '+employerName(s),s.location+' at '+s.start));payrolls.forEach(p=>(p.promises||[]).filter(x=>!x.fulfilled&&x.date).forEach(x=>scheduleNativeReminder('salary_'+x.id,dateTimeMs(x.date,'09:00'),'Salary payment reminder',`${employerById(p.employerId)?.name||'Employer'} — ${salaryMonthLabel(p.earnedMonth)}${x.amount?' — '+money(x.amount):''}${x.endDate?' — by '+niceDate(x.endDate):''}`)));debts.filter(d=>debtRemaining(d)>0&&d.dueDate).forEach(d=>scheduleNativeReminder('debt_'+d.id,dateTimeMs(d.dueDate,'09:00'),d.direction==='owed_to_me'?'Money due to you':'Payment due',`${d.person} — ${money(debtRemaining(d))} remaining`));if(show)toast('Reminders refreshed')}

function normaliseBackupBundle(raw){const b=clone(raw||{});b.profile=b.profile&&typeof b.profile==='object'?b.profile:{};b.settings=b.settings&&typeof b.settings==='object'?b.settings:{role:'Security Officer'};b.shifts=Array.isArray(b.shifts)?b.shifts:[];b.employers=Array.isArray(b.employers)?b.employers:[];b.active=b.active&&typeof b.active==='object'?b.active:null;b.payrolls=Array.isArray(b.payrolls)?b.payrolls:[];b.scheduled=Array.isArray(b.scheduled)?b.scheduled:[];b.debts=Array.isArray(b.debts)?b.debts:[];if(!b.employers.length&&(b.shifts.length||b.profile.employer||b.settings.location||b.settings.rate)){const eid='restored_'+uid(),siteName=String(b.settings.location||'').trim(),sid=siteName?'restored_site_'+uid():'';const e={id:eid,name:String(b.profile.employer||'Restored Employer').trim(),defaultRate:Number(b.settings.rate)||0,payrollRef:'',payDay:1,payOffset:1,notes:'Restored from an earlier backup',sites:siteName?[{id:sid,name:siteName,address:'',rateOverride:null,latitude:null,longitude:null,accuracy:null,capturedAt:''}]:[]};b.employers=[e];b.settings.defaultEmployerId=eid;b.shifts=b.shifts.map(s=>({...s,employerId:s.employerId||eid,employerName:s.employerName||e.name,siteId:s.siteId||(siteName&&String(s.location||'').toLowerCase()===siteName.toLowerCase()?sid:'')}));if(b.active&&!b.active.employerId)b.active={...b.active,employerId:eid,employerName:e.name}}b.employers.forEach(e=>{e.sites=Array.isArray(e.sites)?e.sites:[];e.payDay=Number(e.payDay)||1;e.payOffset=Number(e.payOffset??1)});b.payrolls=b.payrolls.map(p=>({...p,receipts:Array.isArray(p.receipts)?p.receipts:[],promises:Array.isArray(p.promises)?p.promises:[],adjustments:Array.isArray(p.adjustments)?p.adjustments:[]}));return b}
function applyRestore(mode){if(!pendingRestore)return;const b=normaliseBackupBundle(pendingRestore);if(mode==='replace'){profile=b.profile;settings=b.settings;employers=b.employers;active=b.active;shifts=b.shifts;payrolls=b.payrolls;scheduled=b.scheduled;debts=b.debts}else{const empMap={},siteMap={};b.employers.forEach(be=>{let e=employers.find(x=>x.id===be.id)||employers.find(x=>String(x.name).toLowerCase()===String(be.name).toLowerCase());if(!e){e=clone(be);employers.push(e)}else{e.defaultRate=Number(e.defaultRate)||Number(be.defaultRate)||0;e.payrollRef=e.payrollRef||be.payrollRef||'';e.payDay=e.payDay||be.payDay||1;e.payOffset=e.payOffset??be.payOffset??1;e.notes=e.notes||be.notes||'';if(!Array.isArray(e.sites))e.sites=[];(be.sites||[]).forEach(bs=>{let s=e.sites.find(x=>x.id===bs.id)||e.sites.find(x=>String(x.name).toLowerCase()===String(bs.name).toLowerCase());if(!s){s=clone(bs);e.sites.push(s)}siteMap[(be.id||'')+'|'+(bs.id||'')]=s.id})}empMap[be.id]=e.id});const remap=x=>{const eid=empMap[x.employerId]||x.employerId,e=employerById(eid),sid=siteMap[(x.employerId||'')+'|'+(x.siteId||'')]||x.siteId,s=siteById(e,sid);return{...x,employerId:eid,employerName:e?.name||x.employerName,siteId:sid||'',location:s?.name||x.location,siteAddress:s?.address||x.siteAddress||'',siteLatitude:s?.latitude??x.siteLatitude??null,siteLongitude:s?.longitude??x.siteLongitude??null}};mergeUnique(shifts,b.shifts.map(remap));mergeUnique(scheduled,b.scheduled.map(remap));b.payrolls.forEach(bp=>{const eid=empMap[bp.employerId]||bp.employerId;let p=payrolls.find(x=>x.id===bp.id)||payrolls.find(x=>x.employerId===eid&&x.earnedMonth===bp.earnedMonth);if(!p){p={...clone(bp),employerId:eid};payrolls.push(p)}else{mergeUnique(p.receipts,bp.receipts||[]);mergeUnique(p.promises,bp.promises||[]);if(!Array.isArray(p.adjustments))p.adjustments=[];mergeUnique(p.adjustments,bp.adjustments||[])}});mergeUnique(debts,b.debts);profile={...b.profile,...profile};settings={...b.settings,...settings};if(!active&&b.active)active=remap(b.active)}document.getElementById('restoreModal').classList.remove('open');pendingRestore=null;migrate();migrateV31();renderAll();loadProfile();loadSettings();syncAllReminders(false);backupNow(false);toast(mode==='replace'?'Backup restored — current data replaced':'Backup merged with current records')}

